'use client'



import Link from 'next/link'
import Image from 'next/image'
import { usePathname } from 'next/navigation'
import { ReactNode, useEffect, useState } from 'react'
  
import { motion, AnimatePresence } from 'framer-motion'
import { createClient } from '@/lib/supabase/client'
import { setActiveLocationCookie } from './layout-actions'
import {
  BarChart3, BookOpen,
   
   
  
  FileText, Settings, CreditCard, LogOut, Zap, Menu, X, Users, QrCode, TrendingUp, MessageSquare
} from 'lucide-react'
import { GlobalRealtime } from './global-realtime'
import { NotificationCenter } from './notification-center'
import { ServiceWorkerRegistration } from '@/app/components/service-worker-registration'
import { TimeclockWidget } from './timeclock-widget'

export interface NavItem {
  href: string
  label: string
  icon: React.ElementType
  badge?: string
  exact?: boolean
}


const managerItems: NavItem[] = [
  { href: '/dashboard/customers', label: 'CRM & Loyalty', icon: Users },
  { href: '/dashboard/team-performance', label: 'Team Performance', icon: BarChart3 },
  { href: '/dashboard/manage/feedback', label: 'Feedback Inbox', icon: MessageSquare },
  { href: '/dashboard/qr', label: 'QR Generator', icon: QrCode },
  { href: '/dashboard/menu', label: 'Catalog Manager', icon: BookOpen },
  { href: '/dashboard/pages', label: 'Your Pages', icon: FileText },
  { href: '/dashboard/settings', label: 'Settings & Team', icon: Settings },
]

function NavLink({ href, label, icon: Icon, badge, exact, onClick }: {
  href: string; label: string; icon: React.ElementType; badge?: string; exact?: boolean; onClick?: () => void
}) {
  const pathname = usePathname()
  const isActive = exact ? pathname === href : pathname.startsWith(href)

  return (
    <Link
      href={href}
      onClick={onClick}
      className={`group flex items-center gap-3 px-3 py-2.5 rounded-xl text-sm font-medium transition-all duration-200 relative ${
        isActive
          ? 'text-white'
          : 'text-zinc-400 hover:text-white hover:bg-white/5'
      }`}
    >
      {isActive && (
        <motion.div
          layoutId="activeNavBg"
          className="absolute inset-0 bg-gradient-to-r from-violet-600/20 to-indigo-600/10 border border-violet-500/30 rounded-xl shadow-lg shadow-violet-900/20"
          initial={false}
          transition={{ type: 'spring', stiffness: 300, damping: 30 }}
        />
      )}
      {isActive && (
        <motion.span 
          layoutId="activeNavIndicator"
          className="absolute left-0 top-1/2 -translate-y-1/2 w-0.5 h-5 bg-gradient-to-b from-violet-400 to-indigo-400 rounded-full z-10" 
          initial={false}
          transition={{ type: 'spring', stiffness: 300, damping: 30 }}
        />
      )}
      <div className="relative flex items-center gap-3 w-full z-10">
        <Icon className={`w-4 h-4 shrink-0 transition-colors ${isActive ? 'text-violet-400' : 'text-zinc-500 group-hover:text-zinc-300'}`} />
        <span className="flex-1">{label}</span>
        {badge && (
          <span className="px-1.5 py-0.5 text-[10px] font-bold rounded-full bg-emerald-500/20 text-emerald-400 border border-emerald-500/30 animate-pulse">
            {badge}
          </span>
        )}
      </div>
    </Link>
  )
}

export interface InitialDashboardData {
  orgName: string;
  locations: { id: string, name: string }[];
  activeLocationId: string;
  locationSlug: string;
  isOwnerOrManager: boolean;
  userEmail: string;
  credits: number | null;
  dynamicNavItems: NavItem[];
}

export default function ClientLayout({ children, initialData }: { children: ReactNode, initialData: InitialDashboardData }) {
  const [orgName] = useState(initialData.orgName)
  const [locations] = useState<{ id: string, name: string }[]>(initialData.locations)
  const [activeLocationId, setActiveLocationId] = useState(initialData.activeLocationId)
  const [locationSlug] = useState(initialData.locationSlug)
  const [isOwnerOrManager] = useState(initialData.isOwnerOrManager)
  const [time, setTime] = useState('')
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false)
  const [userEmail] = useState(initialData.userEmail)
  const [dynamicNavItems] = useState<NavItem[]>(initialData.dynamicNavItems)

  const [credits] = useState<number | null>(initialData.credits)

  useEffect(() => {
    // Data is now fetched server-side in layout.tsx, so we don't need the client fetcher 
    // unless we want to refresh later. We just need the timer.

    const update = () => setTime(new Date().toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit' }))
    update()
    const i = setInterval(update, 60000)
    return () => clearInterval(i)
     
  }, [])

  const renderNavContent = (onClose?: () => void) => (
    <>
        <div className="p-6 pb-2">
          <Link href="/dashboard" className="flex items-center gap-3 group mb-4" onClick={onClose}>
            <div className="w-10 h-10 flex items-center justify-center group-hover:scale-105 transition-transform duration-300">
              <Image src="/ourmenu-qr-icon.svg" alt="OurMenu Logo" width={32} height={32} className="object-contain" />
            </div>
            <div className="flex flex-col">
              <span className="text-white font-bold tracking-tight leading-tight">OurMenu OS</span>
              {/* OS Version removed as requested */}
            </div>
          </Link>
          {locations.length > 0 && (
            <div className="relative">
              <select
                className="w-full bg-zinc-900 border border-zinc-800 text-zinc-300 text-sm rounded-lg px-3 py-2 appearance-none focus:outline-none focus:border-violet-500 transition-colors"
                value={activeLocationId}
                onChange={async (e) => {
                  const newId = e.target.value
                  setActiveLocationId(newId)
                  await setActiveLocationCookie(newId)
                  window.location.reload()
                }}
              >
                {locations.map((loc) => (
                  <option key={loc.id} value={loc.id}>{loc.name}</option>
                ))}
              </select>
              <div className="absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none text-zinc-500">
                <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" /></svg>
              </div>
            </div>
          )}
        </div>

        <div className="flex-1 overflow-y-auto px-4 py-6 space-y-8 scrollbar-hide">
          <div className="space-y-1">
            <h3 className="px-3 text-xs font-bold text-zinc-500 uppercase tracking-wider mb-3">Daily Operations</h3>
            {dynamicNavItems.map((item) => (
              <NavLink key={item.href} {...item} onClick={onClose} />
            ))}
          </div>

          {isOwnerOrManager && (
            <div className="space-y-1">
              <div className="px-3 flex items-center gap-2 mb-3">
                <h3 className="text-xs font-bold text-zinc-500 uppercase tracking-wider">Management</h3>
                <div className="h-px flex-1 bg-zinc-800/50"></div>
              </div>
              {managerItems.map((item) => (
                <NavLink key={item.href} {...item} onClick={onClose} />
              ))}
            </div>
          )}

          {(userEmail === (process.env.ADMIN_EMAIL || 'kryptopacy@gmail.com')) && (
            <div className="space-y-1">
              <div className="px-3 flex items-center gap-2 mb-3 mt-4">
                <h3 className="text-xs font-bold text-violet-500 uppercase tracking-wider">Superadmin</h3>
                <div className="h-px flex-1 bg-violet-500/20"></div>
              </div>
              <NavLink href="/dashboard/admin" label="Developer Console" icon={Zap} onClick={onClose} />
            </div>
          )}
        </div>

        <div className="p-4 mt-auto">
          {credits !== null && (
            <Link href="/dashboard/billing" className="flex items-center justify-between px-3 py-2.5 bg-violet-500/10 hover:bg-violet-500/20 rounded-xl border border-violet-500/20 mb-4 transition-colors group" onClick={onClose}>
              <div className="flex items-center gap-2">
                <Zap className="w-4 h-4 text-violet-400" />
                <span className="text-xs font-bold text-violet-100">Credits</span>
              </div>
              <span className="text-xs font-black text-violet-400 group-hover:scale-110 transition-transform">{credits}</span>
            </Link>
          )}
          {locationSlug && (
            <a 
              href={`/m/${locationSlug}`} 
              target="_blank" 
              rel="noreferrer"
              className="flex items-center justify-center gap-2 w-full py-3 px-4 bg-zinc-900 hover:bg-zinc-800 border border-zinc-800 hover:border-zinc-700 text-white text-sm font-medium rounded-xl transition-all mb-4 group"
            >
              Live Preview
              <svg className="w-4 h-4 text-zinc-500 group-hover:text-white transition-colors" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14" /></svg>
            </a>
          )}
          
          <div className="flex items-center justify-between px-3 py-2 bg-black/40 rounded-xl border border-white/5">
            <div className="flex items-center gap-2">
              <div className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse shadow-[0_0_10px_rgba(16,185,129,0.5)]" />
              <span className="text-xs font-medium text-zinc-400">System Active</span>
            </div>
            <span className="text-xs font-mono text-zinc-500">{time}</span>
          </div>
        </div>
    </>
  )

  return (
    <div className="min-h-screen bg-black flex selection:bg-violet-500/30 print:bg-white">
      <GlobalRealtime />
      <ServiceWorkerRegistration />
      
      {/* Desktop Sidebar */}
      <aside className="hidden md:flex w-72 flex-col bg-[#0a0a0a] border-r border-white/5 relative z-20 print:hidden">
        {renderNavContent()}
      </aside>

      {/* Mobile Header & Menu */}
      <div className="md:hidden fixed top-0 left-0 right-0 h-16 bg-[#0a0a0a]/90 backdrop-blur-md border-b border-white/5 z-50 flex items-center justify-between px-4 print:hidden">
        <div className="flex items-center gap-2">
          <div className="w-8 h-8 flex items-center justify-center">
            <Image src="/ourmenu-qr-icon.svg" alt="OurMenu Logo" width={24} height={24} className="object-contain" />
          </div>
          <span className="text-white font-bold tracking-tight">OurMenu OS</span>
        </div>
        <div className="flex items-center gap-4">
          <NotificationCenter />
          <button onClick={() => setMobileMenuOpen(true)} className="text-zinc-400 hover:text-white">
            <Menu className="w-6 h-6" />
          </button>
        </div>
      </div>

      {mobileMenuOpen && (
        <div className="md:hidden fixed inset-0 z-[60] bg-black/80 backdrop-blur-sm print:hidden">
          <div className="absolute right-0 top-0 bottom-0 w-80 bg-[#0a0a0a] border-l border-white/5 shadow-2xl flex flex-col animate-in slide-in-from-right duration-300">
            <div className="flex justify-end p-4">
              <button onClick={() => setMobileMenuOpen(false)} className="text-zinc-400 hover:text-white bg-zinc-900 p-2 rounded-full">
                <X className="w-5 h-5" />
              </button>
            </div>
            {renderNavContent(() => setMobileMenuOpen(false))}
          </div>
        </div>
      )}

      {/* Main Content */}
      <main className="flex-1 flex flex-col min-h-screen relative pt-16 md:pt-0 print:pt-0">
        <div className="absolute top-0 right-0 p-6 z-10 hidden md:block print:hidden">
          <div className="flex items-center gap-4 bg-zinc-900/50 backdrop-blur-md border border-zinc-800/50 px-4 py-2 rounded-full shadow-xl">
            {locationSlug && <TimeclockWidget locationId={locationSlug} />}
            <div className="w-px h-4 bg-zinc-800"></div>
            <NotificationCenter />
            <div className="w-px h-4 bg-zinc-800"></div>
            {orgName ? (
              <span className="text-xs font-bold text-zinc-400 uppercase tracking-widest">{orgName}</span>
            ) : (
              <div className="h-3 w-24 bg-zinc-800 rounded-full animate-pulse" />
            )}
          </div>
        </div>
        <div className="flex-1 p-4 md:p-10 max-w-[1600px] mx-auto w-full print:p-0">
          {children}
        </div>
      </main>
    </div>
  )
}

'use server'

import { createClient } from '@/lib/supabase/server'
import { revalidatePath } from 'next/cache'
import { authActionClient } from '@/lib/safe-action'
import { z } from 'zod'
import { zfd } from 'zod-form-data'

export const updateSetting = authActionClient
  .schema(zfd.formData(z.any()))
  .action(async ({ parsedInput: formData, ctx: { user } }) => {
    const supabase = await createClient()

    if (user.email !== (process.env.ADMIN_EMAIL || 'kryptopacy@gmail.com')) {
      throw new Error('Unauthorized')
    }

    const key = formData.get('key') as string
    const isJson = formData.get('is_json') === 'true'

    
    let value: Record<string, any> = {}

    if (isJson) {
      const rawJson = formData.get('json_value') as string
      try {
        value = JSON.parse(rawJson)
      } catch {
        throw new Error('Invalid JSON format')
      }
    } else {
      // Collect all other keys into an object
      formData.forEach((val: FormDataEntryValue, k: string) => {
        if (k !== 'key' && k !== 'is_json' && !k.startsWith('$ACTION')) {
          // Automatically cast numbers for pricing
          if (key === 'pricing') {
            value[k] = Number(val)
          } else {
            value[k] = val
          }
        }
      })
    }

    
    const { error } = await (supabase as unknown)
      .from('system_settings')
      .upsert({
        key,
        value,
        updated_by: user.id
      })

    if (error) {
      console.error('Failed to update setting', error)
      throw new Error('Failed to update setting')
    }

    revalidatePath('/', 'layout')
    return { success: true }
  })

export const overrideTenantPlan = authActionClient
  .schema(zfd.formData(z.any()))
  .action(async ({ parsedInput: formData, ctx: { user } }) => {
    const supabase = await createClient()

    if (user.email !== (process.env.ADMIN_EMAIL || 'kryptopacy@gmail.com')) {
      throw new Error('Unauthorized')
    }

    const orgId = formData.get('org_id') as string
    const plan = formData.get('subscription_plan') as string
    const status = formData.get('subscription_status') as string
    const credits = Number(formData.get('purchased_credits')) || 0

    
    const { error } = await (supabase as unknown)
      .from('organizations')
      .update({
        subscription_plan: plan,
        subscription_status: status,
        purchased_credits: credits,
        updated_at: new Date().toISOString()
      })
      .eq('id', orgId)

    if (error) {
      console.error('Override error:', error)
      throw new Error('Failed to override tenant plan')
    }

    revalidatePath('/dashboard/admin')
    return { success: true }
  })

'use server'

import { createClient } from '@/lib/supabase/server'
import { getOrCreateBillingPlan, initializeSubscription } from '@/lib/payments/billing'
import { redirect } from 'next/navigation'

import { getPricingSettings } from '@/lib/utils/settings'
import { getUsdToNgnRate } from '@/lib/payments/exchange'
import { authActionClient } from '@/lib/safe-action'
import { z } from 'zod'
import { zfd } from 'zod-form-data'

export const subscribeToLite = authActionClient
  .schema(zfd.formData(z.object({
    organization_id: z.string(),
    currency: z.string().optional().default('NGN')
  })))
  .action(async ({ parsedInput: { organization_id, currency }, ctx: { user } }) => {
    const supabase = await createClient()

    const { cookies } = await import('next/headers')
    const cookieStore = await cookies()
    if (cookieStore.get('demo_mode')?.value === '1') {
      throw new Error('Billing is disabled in Demo Mode')
    }

    const { data: org } = await supabase
      .from('organizations')
      .select('name')
      .eq('id', organization_id)
      .single()

    if (!org) throw new Error('Organization not found')

    const rate = await getUsdToNgnRate()
    const pricing = await getPricingSettings()

    const baseNgn = pricing.lite_monthly_ngn || 14999
    let amountMinor = 0
    if (currency === 'USD') {
      const amountUsd = baseNgn / rate
      amountMinor = Math.round(amountUsd * 100) // cents
    } else {
      amountMinor = baseNgn * 100 // kobo
    }

    const planCode = await getOrCreateBillingPlan(organization_id, org.name, 'lite', amountMinor, currency)
    const authUrl = await initializeSubscription(user.email!, planCode, organization_id, 'lite', currency)

    redirect(authUrl)
  })

export const subscribeToPro = authActionClient
  .schema(zfd.formData(z.object({
    organization_id: z.string(),
    currency: z.string().optional().default('NGN')
  })))
  .action(async ({ parsedInput: { organization_id, currency }, ctx: { user } }) => {
    const supabase = await createClient()

    const { data: org } = await supabase
      .from('organizations')
      .select('name')
      .eq('id', organization_id)
      .single()

    if (!org) throw new Error('Organization not found')

    const rate = await getUsdToNgnRate()
    const pricing = await getPricingSettings()

    const baseNgn = pricing.pro_monthly_ngn || 49999
    let amountMinor = 0
    if (currency === 'USD') {
      const amountUsd = baseNgn / rate
      amountMinor = Math.round(amountUsd * 100) // cents
    } else {
      amountMinor = baseNgn * 100 // kobo
    }

    const planCode = await getOrCreateBillingPlan(organization_id, org.name, 'pro', amountMinor, currency)
    const authUrl = await initializeSubscription(user.email!, planCode, organization_id, 'pro', currency)

    redirect(authUrl)
  })

export const cancelSubscription = authActionClient
  .schema(zfd.formData(z.object({
    organization_id: z.string()
  })))
  .action(async ({ parsedInput: { organization_id }, ctx: { user } }) => {
    const supabase = await createClient()

    await supabase
      .from('organizations')
      .update({ 
        subscription_status: 'inactive',
        subscription_plan: 'free'
      })
      .eq('id', organization_id)

    redirect('/dashboard/billing')
  })

export const buyCredits = authActionClient
  .schema(zfd.formData(z.object({
    organization_id: z.string(),
    credits: z.string().transform(v => parseInt(v, 10))
  })))
  .action(async ({ parsedInput: { organization_id, credits }, ctx: { user } }) => {
    const supabase = await createClient()

    if (!organization_id || credits <= 0) throw new Error('Invalid data')

    const { data: org } = await supabase
      .from('organizations')
      .select('name, purchased_credits')
      .eq('id', organization_id)
      .single()

    if (!org) throw new Error('Org not found')

    // 3. Initialize Paystack payment for credits
    const amountMinor = credits === 10 ? 600000 : credits === 25 ? 1200000 : 2000000; // NGN 6k, 12k, 20k

    const response = await fetch('https://api.paystack.co/transaction/initialize', {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${process.env.PAYSTACK_SECRET_KEY}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        email: user.email!,
        amount: amountMinor,
        currency: 'NGN',
        callback_url: `${process.env.NEXT_PUBLIC_SITE_URL}/dashboard/billing/verify`,
        metadata: {
          organization_id: organization_id,
          is_credit_pack: true,
          credits: credits
        }
      }),
    })

    const data = await response.json()

    if (!data.status) {
      throw new Error(data.message || 'Failed to initialize payment')
    }

    redirect(data.data.authorization_url)
  })

'use client'

import { useState } from 'react'

type StockAlert = 'critical' | 'order_soon' | 'sufficient'
type Trend = 'rising' | 'stable' | 'declining'

interface ForecastItem {
  item_name: string
  trend: Trend
  predicted_units_next_7d: number
  stock_alert: StockAlert
  insight: string
}

interface ForecastClientProps {
  locationId: string
}

const TrendIcon = ({ trend }: { trend: Trend }) => {
  if (trend === 'rising') return (
    <span title="Rising" className="flex items-center gap-1 text-emerald-400 text-xs font-bold">
      <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M13 7h8m0 0v8m0-8l-8 8-4-4-6 6" /></svg>
      Rising
    </span>
  )
  if (trend === 'declining') return (
    <span title="Declining" className="flex items-center gap-1 text-red-400 text-xs font-bold">
      <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M13 17h8m0 0v-8m0 8l-8-8-4 4-6-6" /></svg>
      Declining
    </span>
  )
  return (
    <span title="Stable" className="flex items-center gap-1 text-yellow-400 text-xs font-bold">
      <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M5 12h14" /></svg>
      Stable
    </span>
  )
}

const AlertBadge = ({ alert }: { alert: StockAlert }) => {
  const map = {
    critical: { label: 'âš ï¸ Stock Critical', cls: 'bg-red-500/20 text-red-400 border border-red-500/50' },
    order_soon: { label: 'ðŸ“¦ Order Soon', cls: 'bg-yellow-500/20 text-yellow-400 border border-yellow-500/50' },
    sufficient: { label: '✅ Sufficient', cls: 'bg-emerald-500/20 text-emerald-400 border border-emerald-500/50' },
  }
  const { label, cls } = map[alert]
  return <span className={`px-2.5 py-1 rounded-full text-xs font-semibold ${cls}`}>{label}</span>
}

export function ForecastClient({ locationId }: ForecastClientProps) {
  const [forecasts, setForecasts] = useState<ForecastItem[]>([])
  const [message, setMessage] = useState<string | null>(null)
  const [isLoading, setIsLoading] = useState(false)
  const [hasGenerated, setHasGenerated] = useState(false)

  const maxPredicted = Math.max(...forecasts.map(f => f.predicted_units_next_7d), 1)

  const handleGenerate = async () => {
    setIsLoading(true)
    setMessage(null)
    try {
      const res = await fetch('/api/ai/forecast', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ locationId })
      })
      const data = await res.json()
      if (data.forecasts) setForecasts(data.forecasts)
      if (data.message) setMessage(data.message)
      setHasGenerated(true)

    } catch (_e) {
      setMessage('Failed to generate forecast. Please try again.')
    } finally {
      setIsLoading(false)
    }
  }

  return (
    <div>
      {/* Hero CTA */}
      <div className="flex items-center justify-between mb-8">
        <div>
          {hasGenerated
            ? <p className="text-zinc-400 text-sm">Showing AI-powered demand predictions for the next 7 days.</p>
            : <p className="text-zinc-400 text-sm">Analyse your last 30 days of sales to predict what to stock up on.</p>
          }
        </div>
        <button
          onClick={handleGenerate}
          disabled={isLoading}
          className="flex items-center gap-2 px-5 py-2.5 bg-gradient-to-r from-violet-600 to-indigo-600 text-white text-sm font-bold rounded-xl hover:from-violet-500 hover:to-indigo-500 disabled:opacity-50 transition-all shadow-lg shadow-indigo-900/30"
        >
          {isLoading ? (
            <>
              <span className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin"></span>
              Analysing sales data...
            </>
          ) : (
            <>
              <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
              {hasGenerated ? 'Regenerate Forecast' : 'Generate Forecast'}
            </>
          )}
        </button>
      </div>

      {/* Empty / Message state */}
      {!hasGenerated && !isLoading && (
        <div className="flex flex-col items-center justify-center py-28 text-center border border-dashed border-zinc-800 rounded-2xl">
          <div className="w-16 h-16 bg-violet-500/10 rounded-2xl flex items-center justify-center mb-4">
            <svg className="w-8 h-8 text-violet-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z" /></svg>
          </div>
          <h3 className="text-white font-semibold text-lg mb-2">Ready to forecast</h3>
          <p className="text-zinc-500 text-sm max-w-xs">Hit &quot;Generate Forecast&quot; and our AI will crunch 30 days of sales data to tell you exactly what to restock.</p>
        </div>
      )}

      {isLoading && (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {Array.from({ length: 6 }).map((_, i) => (
            <div key={i} className="h-40 bg-zinc-900 rounded-xl animate-pulse border border-zinc-800" />
          ))}
        </div>
      )}

      {message && !isLoading && (
        <div className="p-5 bg-zinc-900 border border-zinc-800 rounded-xl text-zinc-400 text-sm text-center">
          {message}
        </div>
      )}

      {/* Forecast Grid */}
      {!isLoading && forecasts.length > 0 && (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {forecasts.map((item) => {
            const barWidth = Math.max(4, Math.round((item.predicted_units_next_7d / maxPredicted) * 100))
            const barColor = item.stock_alert === 'critical' ? 'bg-red-500' : item.stock_alert === 'order_soon' ? 'bg-yellow-500' : 'bg-emerald-500'

            return (
              <div
                key={item.item_name}
                className="bg-zinc-900 border border-zinc-800 rounded-xl p-5 flex flex-col gap-3 hover:border-zinc-700 transition-colors"
              >
                <div className="flex items-start justify-between gap-2">
                  <h3 className="font-semibold text-white text-sm leading-snug">{item.item_name}</h3>
                  <AlertBadge alert={item.stock_alert} />
                </div>

                {/* Demand bar */}
                <div>
                  <div className="flex justify-between text-xs text-zinc-500 mb-1.5">
                    <span>Predicted demand (next 7d)</span>
                    <span className="font-bold text-white">{item.predicted_units_next_7d} units</span>
                  </div>
                  <div className="h-2 bg-zinc-800 rounded-full overflow-hidden">
                    <div
                      className={`h-full ${barColor} rounded-full transition-all duration-700`}
                      style={{ width: `${barWidth}%` }}
                    />
                  </div>
                </div>

                <div className="flex items-center justify-between">
                  <TrendIcon trend={item.trend} />
                  <p className="text-zinc-400 text-xs italic text-right max-w-[60%]">{item.insight}</p>
                </div>
              </div>
            )
          })}
        </div>
      )}
    </div>
  )
}

import { Database } from '@/lib/supabase/types'
import { createClient } from '@/lib/supabase/server'
import { redirect } from 'next/navigation'
import { createCategory } from './actions'
import { CategoryTabs } from './category-tabs'
import { TranslateMenuButton } from './translate-menu-button'
import { cookies } from 'next/headers'

export default async function MenuManagerPage() {
  const supabase = await createClient()
  const { data: userData } = await supabase.auth.getUser()
  const user = userData?.user
  if (!user) {
    // We handle the redirect below
  }

  if (!user) {
    redirect('/login')
  }
  const userId = user!.id

  let org: { id: string } | null = null
  let role = 'viewer'
  let menu: { id: string } | null = null
  let categories: (Database['public']['Tables']['menu_categories']['Row'] & { menu_items?: Database['public']['Tables']['menu_items']['Row'][] })[] = []

  const { data: member } = await supabase
    .from('organization_members')
    .select('role, organizations(id)')
    .eq('user_id', userId)
    .single()

  if (member && member.organizations) {
    org = member.organizations
    role = member.role
  } else {
    const { data } = await supabase
      .from('organizations')
      .select('id')
      .eq('created_by', userId)
      .single()
    org = data
  
    role = 'owner'
  }

  const cookieStore = await cookies()
  const savedLocId = cookieStore.get('ourmenu_active_location_id')?.value

  let locationId = savedLocId
  if (!locationId) {
    const { data: loc } = await supabase.from('locations').select('id').eq('organization_id', org?.id || '').limit(1).single()
    locationId = loc?.id
  }
  const activeLocationId = locationId || ''

  let menuQuery = supabase
    .from('menus')
    .select('id')
    .eq('organization_id', org?.id || '')
    
  if (activeLocationId) {
    menuQuery = menuQuery.eq('location_id', activeLocationId)
  }

  const { data: menuData } = await menuQuery.single()
  
  menu = menuData

  if (menu) {
    const { data: catData } = await supabase
      .from('menu_categories')
      .select('*, menu_items(*)')
      .eq('menu_id', menu.id)
      .order('sort_order')
    
    categories = catData || []
  }

  if (!org || !menu) {
    return (
      <div className="max-w-5xl">
        <h1 className="text-2xl font-bold text-white mb-6">Primary Catalog</h1>
        <div className="rounded-xl border border-yellow-800 bg-yellow-900/20 p-6">
          <p className="text-yellow-400">Please complete your Business Settings to create your first menu.</p>
        </div>
      </div>
    )
  }

  return (
    <div className="max-w-5xl">
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between mb-8 gap-4">
        <h1 className="text-2xl font-bold text-white">Primary Catalog</h1>
        <TranslateMenuButton orgId={org.id} categories={categories} />
      </div>

      <CategoryTabs categories={categories} orgId={org.id} menuId={menu.id} />
    </div>
  )
}

'use client'



import { useState, useEffect, useOptimistic } from 'react'
import { useTranslations } from 'next-intl'
import { createClient } from '@/lib/supabase/client'
import { toast } from 'sonner'
import { Database } from '@/lib/supabase/types'
import { ServiceRequestsPanel } from './components/service-requests-panel'
import { ActiveOrdersGrid } from './components/active-orders-grid'
import { StockManagementView } from './components/stock-management-view'
import { OrderHistoryView } from './components/order-history-view'
import { mapSupabaseOrderToUI } from '@/lib/utils/transformers'
import { UIOrder } from '@/lib/types/frontend'
import { useOfflineSync } from '@/hooks/use-offline-sync'
import { QueuedAction } from '@/lib/stores/offline-queue-store'
import { markOrderPaidOffline, completeOrderAction, cancelOrderAction } from './actions'
import { OfflineIndicator } from './components/offline-indicator'
import { HardwareSettingsView } from './components/hardware-settings-view'
import { usePrinterStore } from '@/lib/stores/printer-store'
import { printOrder } from '@/lib/utils/printer'

type ServiceRequestRow = Database['public']['Tables']['service_requests']['Row']
type MenuItemRow = Database['public']['Tables']['menu_items']['Row']
type OrderPayload = { eventType: string, new: Database['public']['Tables']['orders']['Row'] }
type ServiceRequestPayload = { eventType: string, new: ServiceRequestRow }
type MenuItemPayload = { eventType: string, new: MenuItemRow }

interface OrdersClientProps {
  organizationId: string
  locationId: string
  initialOrders: UIOrder[]
  initialServiceRequests: ServiceRequestRow[]
  initialMenuItems?: MenuItemRow[]
  currentUserId: string
  billingMode?: string
  templateType?: string
}

export function OrdersClient({ organizationId, locationId, initialOrders, initialServiceRequests, initialMenuItems = [], currentUserId, billingMode = 'standard_checkout', templateType = 'catalog' }: OrdersClientProps) {
  const supabase = createClient()
  const [orders, setOrders] = useState(initialOrders)
  const [serviceRequests, setServiceRequests] = useState(initialServiceRequests)
  const [menuItems, setMenuItems] = useState(initialMenuItems)
  const [activeTab, setActiveTab] = useState<'orders' | 'history' | 'stock' | 'hardware'>('orders')
  const { mode, ipAddress, autoPrintReceipts } = usePrinterStore()
  const t = useTranslations('Dashboard')

  const onSyncAction = async (action: QueuedAction) => {
    switch (action.type) {
      case 'toggleStock':
        const { error } = await supabase.from('menu_items').update({ availability_status: action.payload.newStatus }).eq('id', action.payload.itemId)
        return !error
      case 'claimOrder':
        const { error: claimError } = await supabase.rpc('claim_order', { p_order_id: action.payload.orderId, p_prep_time_minutes: action.payload.minutes })
        return !claimError
      case 'resolveServiceRequest':
        const { error: srError } = await supabase.from('service_requests').update({ status: 'resolved' }).eq('id', action.payload.id)
        return !srError
      case 'markOrderPaid':
        const resPaid = await markOrderPaidOffline({ orderId: action.payload.orderId })
        return !resPaid?.serverError && !resPaid?.validationErrors
      case 'completeOrder':
        const resComp = await completeOrderAction({ orderId: action.payload.orderId })
        return !resComp?.serverError && !resComp?.validationErrors
      default:
        return true
    }
  }

  const { executeOrQueue } = useOfflineSync(onSyncAction)

  useEffect(() => {
    // Subscribe to Orders
    const ordersSubscription = supabase
      .channel('orders-channel')
      .on('postgres_changes', { 
        event: '*', 
        schema: 'public', 
        table: 'orders',
        filter: `location_id=eq.${locationId}`
      }, (payload: unknown) => {
        const orderPayload = payload as OrderPayload
        // Fetch full order with items if INSERT
        if (orderPayload.eventType === 'INSERT') {
          supabase
            .from('orders')
            .select('*, order_items(*)')
            .eq('id', orderPayload.new.id)
            .single()
            .then(({ data }: { data: unknown }) => {
              const fullData = data ? mapSupabaseOrderToUI(data as Parameters<typeof mapSupabaseOrderToUI>[0]) : null
              if (fullData) {
                setOrders((prev) => [fullData, ...prev])
                if (fullData.status === 'paid' || fullData.status === 'pending') {
                  toast.success(`New Order Received! Table: ${fullData.table_identifier}`)
                }
              }
            })
        } else if (orderPayload.eventType === 'UPDATE') {
          setOrders((prev) => {
            const oldOrder = prev.find(o => o.id === orderPayload.new.id)
            if (oldOrder && oldOrder.status !== 'paid' && orderPayload.new.status === 'paid') {
              toast.success(`Payment Confirmed! Table: ${orderPayload.new.table_identifier}`)
            }
            return prev.map(o => o.id === orderPayload.new.id ? { ...o, ...orderPayload.new } : o)
          })
        }
      })
      .subscribe()

    // Subscribe to Service Requests
    const serviceRequestsSubscription = supabase
      .channel('service-requests-channel')
      .on('postgres_changes', { 
        event: '*', 
        schema: 'public', 
        table: 'service_requests',
        filter: `location_id=eq.${locationId}`
      }, (payload: unknown) => {
        const srPayload = payload as ServiceRequestPayload
        if (srPayload.eventType === 'INSERT') {
          setServiceRequests((prev) => [...prev, srPayload.new])
        } else if (srPayload.eventType === 'UPDATE') {
          setServiceRequests((prev) => prev.map(r => r.id === srPayload.new.id ? srPayload.new : r))
        }
      })
      .subscribe()

      .subscribe()

    // Subscribe to Menu Items
    const menuSubscription = supabase
      .channel('menu-channel')
      .on('postgres_changes', { 
        event: 'UPDATE', 
        schema: 'public', 
        table: 'menu_items',
        filter: `organization_id=eq.${organizationId}`
      }, (payload: unknown) => {
        const itemPayload = payload as MenuItemPayload
        setMenuItems((prev: MenuItemRow[]) => prev.map((item: MenuItemRow) => item.id === itemPayload.new.id ? { ...item, ...itemPayload.new } : item))
      })
      .subscribe()

    return () => {
      supabase.removeChannel(ordersSubscription)
      supabase.removeChannel(serviceRequestsSubscription)
      supabase.removeChannel(menuSubscription)
    }
  }, [organizationId, locationId, supabase])  

  // Global KDS Hotkeys (Only for restaurant template)
  useEffect(() => {
    if (templateType !== 'restaurant') return
    
    const handleKeyDown = (e: KeyboardEvent) => {
      // Don't trigger if user is typing in an input
      if (['INPUT', 'TEXTAREA', 'SELECT'].includes((e.target as HTMLElement).tagName)) return
      
      switch (e.key) {
        case 'm':
        case 'M':
          e.preventDefault()
          setActiveTab('stock')
          break
        case 'o':
        case 'O':
          e.preventDefault()
          setActiveTab('orders')
          break
        case 'p':
        case 'P':
          e.preventDefault()
          // Automatically print the oldest active order
          const printOrderObj = orders.find(o => o.status !== 'completed' && o.status !== 'cancelled')
          if (printOrderObj) {
            printOrder(printOrderObj, { mode, ipAddress, businessName: 'OurMenu OS' })
          }
          break
        case ' ': // Spacebar
          e.preventDefault()
          // Fast Claim / Complete oldest pending/preparing order
          const claimable = orders.find(o => o.status === 'pending' || (o.status === 'paid' && !o.assigned_staff_id) || (o.status === 'preparing' && o.assigned_staff_id === currentUserId))
          if (claimable) {
            if (claimable.status === 'preparing') {
               handleCompleteOrder(claimable.id)
            } else {
               // Simulate button click to prompt for time (or default to 15m for hotkey)
               handleClaimOrderFast(claimable.id)
            }
          }
          break
      }
    }

    window.addEventListener('keydown', handleKeyDown)
    return () => window.removeEventListener('keydown', handleKeyDown)
  }, [templateType, orders, currentUserId, mode, ipAddress])

  const handleClaimOrderFast = async (orderId: string) => {
    // Fast path for hotkey
    await executeOrQueue(
      { type: 'claimOrder', payload: { orderId, minutes: 15 } },
      () => {},
      async () => {
        const { data, error } = await supabase.rpc('claim_order', {
          p_order_id: orderId,
          p_prep_time_minutes: 15
        })
        if (error) return false
        if (data !== false) toast.success('Order claimed successfully!')
        return true
      }
    )
  }

  const urgencyWeight: Record<string, number> = { 'critical': 3, 'standard': 2, 'low': 1 }
  const basePendingRequests = serviceRequests
    .filter(r => r.status === 'pending')
    .sort((a, b) => {
      const weightA = urgencyWeight[a.urgency_tier || 'standard'] || 0
      const weightB = urgencyWeight[b.urgency_tier || 'standard'] || 0
      return weightB - weightA // Critical first
    })

  const [optimisticRequests, addOptimisticResolve] = useOptimistic(
    basePendingRequests,
    (state, resolvedId: string) => state.filter(r => r.id !== resolvedId)
  )

  const activeOrders = orders.filter(o => o.status !== 'completed')
  const completedOrders = orders.filter(o => o.status === 'completed')

  const toggleStock = async (itemId: string, currentStatus: string) => {
    const newStatus = currentStatus === 'available' ? 'sold_out' : 'available'
    const previousItems = [...menuItems]

    await executeOrQueue(
      { type: 'toggleStock', payload: { itemId, newStatus } },
      () => setMenuItems((prev: MenuItemRow[]) => prev.map((i: MenuItemRow) => i.id === itemId ? { ...i, availability_status: newStatus } : i)),
      async () => {
        const { error } = await supabase.from('menu_items').update({ availability_status: newStatus }).eq('id', itemId)
        if (error) {
          setMenuItems(previousItems)
          toast.error('Failed to update stock status: ' + (error as Error).message)
          return false
        }
        toast.success(`Item marked as ${newStatus === 'available' ? 'Available' : 'Sold Out'}`)
        return true
      }
    )
  }

  const handleClaimOrder = async (orderId: string) => {
    const timeInput = window.prompt('Estimated time to prepare (in minutes)?', '15')
    if (!timeInput) return

    const minutes = parseInt(timeInput, 10)
    if (isNaN(minutes)) {
      toast.error('Please enter a valid number of minutes.')
      return
    }

    await executeOrQueue(
      { type: 'claimOrder', payload: { orderId, minutes } },
      () => {}, // Handled optimistically inside ActiveOrdersGrid
      async () => {
        const { data, error } = await supabase.rpc('claim_order', {
          p_order_id: orderId,
          p_prep_time_minutes: minutes
        })
        if (error) {
          toast.error('Failed to claim order: ' + (error as Error).message)
          return false
        }
        if (data === false) {
          toast.error('Order was already claimed by another staff member, or limit reached.')
        } else {
          toast.success('Order claimed successfully!')
        }
        return true
      }
    )
  }

  const handleMarkPaidOffline = async (orderId: string) => {
    await executeOrQueue(
      { type: 'markOrderPaid', payload: { orderId } },
      () => {}, // Handled optimistically inside ActiveOrdersGrid
      async () => {
        const res = await markOrderPaidOffline({ orderId })
        if (res?.serverError || res?.validationErrors) {
          toast.error('Failed to confirm payment')
          return false
        }
        toast.success('Payment confirmed!')
        return true
      }
    )
  }

  const handleCompleteOrder = async (orderId: string) => {
    await executeOrQueue(
      { type: 'completeOrder', payload: { orderId } },
      () => {}, // Handled optimistically inside ActiveOrdersGrid
      async () => {
        const res = await completeOrderAction({ orderId })
        if (res?.serverError || res?.validationErrors) {
          toast.error('Failed to complete order')
          return false
        }
        toast.success('Order completed! Feedback email sent.')
        
        // Auto-print receipt if hardware is configured
        if (autoPrintReceipts) {
          const order = activeOrders.find(o => o.id === orderId)
          if (order) {
            printOrder(order, { mode, ipAddress, businessName: 'OurMenu OS' })
          }
        }
        return true
      }
    )
  }

  const handleCancelOrder = async (orderId: string, reason: string, restock: boolean) => {
    await executeOrQueue(
      { type: 'cancelOrder', payload: { orderId, reason, restock } },
      () => {}, 
      async () => {
        const res = await cancelOrderAction({ orderId, reason, restock })
        if (res?.serverError || res?.validationErrors) {
          toast.error('Failed to cancel order')
          return false
        }
        toast.success(`Order cancelled. ${restock ? 'Inventory restocked.' : ''}`)
        return true
      }
    )
  }

  return (
    <div className="flex-1 flex flex-col mt-8">
      <OfflineIndicator />
      <div className="flex space-x-2 mb-6">
        <button 
          onClick={() => setActiveTab('orders')}
          className={`px-4 py-2 rounded-lg font-medium text-sm transition-colors ${activeTab === 'orders' ? 'bg-blue-600 text-white shadow-md' : 'bg-zinc-800 text-zinc-400 hover:bg-zinc-700 hover:text-white border border-zinc-700/50'}`}
        >
          Active Orders
        </button>
        <button 
          onClick={() => setActiveTab('history')}
          className={`px-4 py-2 rounded-lg font-medium text-sm transition-colors ${activeTab === 'history' ? 'bg-blue-600 text-white shadow-md' : 'bg-zinc-800 text-zinc-400 hover:bg-zinc-700 hover:text-white border border-zinc-700/50'}`}
        >
          History
        </button>
        <button 
          onClick={() => setActiveTab('stock')}
          className={`px-4 py-2 rounded-lg font-medium text-sm transition-colors flex items-center gap-2 ${activeTab === 'stock' ? 'bg-blue-600 text-white shadow-md' : 'bg-zinc-800 text-zinc-400 hover:bg-zinc-700 hover:text-white border border-zinc-700/50'}`}
        >
          <span className={`w-2 h-2 rounded-full ${menuItems.some((i: MenuItemRow) => i.availability_status === 'sold_out') ? 'bg-red-500' : 'bg-green-500'}`}></span>
          Live Stock
        </button>
        <button 
          onClick={() => setActiveTab('hardware')}
          className={`px-4 py-2 rounded-lg font-medium transition-colors ${activeTab === 'hardware' ? 'bg-zinc-800 text-white' : 'text-zinc-400 hover:text-white'}`}
        >
          {t('hardwareSettings')}
        </button>
      </div>

      {activeTab === 'orders' ? (
        <div className="flex-1 grid grid-cols-1 lg:grid-cols-3 gap-6 overflow-hidden">
          <ServiceRequestsPanel 
            pendingRequests={optimisticRequests} 
            onResolve={async (id) => { 
              await executeOrQueue(
                { type: 'resolveServiceRequest', payload: { id } },
                () => addOptimisticResolve(id),
                async () => {
                  const { error } = await supabase.from('service_requests').update({ status: 'resolved' }).eq('id', id)
                  return !error
                }
              )
            }} 
          />
          <ActiveOrdersGrid 
            activeOrders={activeOrders} 
            currentUserId={currentUserId} 
            billingMode={billingMode} 
            templateType={templateType}
            onClaimOrder={handleClaimOrder} 
            onMarkPaidOffline={handleMarkPaidOffline}
            onCompleteOrder={handleCompleteOrder}
            onCancelOrder={handleCancelOrder}
          />
        </div>
      ) : activeTab === 'history' ? (
        <OrderHistoryView 
          organizationId={organizationId} 
          locationId={locationId} 
          initialOrders={completedOrders} 
        />
      ) : activeTab === 'hardware' ? (
        <HardwareSettingsView />
      ) : (
        <StockManagementView 
          menuItems={menuItems} 
          onToggleStock={toggleStock} 
        />
      )}
    </div>
  )
}

'use server'

import { createClient } from '@/lib/supabase/server'
import { revalidatePath } from 'next/cache'
import { redirect } from 'next/navigation'
import type { Json } from '@/lib/supabase/types'
import { z } from 'zod'
import { zfd } from 'zod-form-data'
import { authActionClient } from '@/lib/safe-action'

const MAX_FILE_SIZE = 5 * 1024 * 1024 // 5MB
const ACCEPTED_IMAGE_TYPES = ['image/jpeg', 'image/jpg', 'image/png', 'image/webp']

// ─── Business Type Setup ───────────────────────────────────────────────────────

export const setBusinessTypeAction = authActionClient
  .schema(zfd.formData({
    businessType: zfd.text(),
    orgId: zfd.text(),
    mode: zfd.text()
  }))
  .action(async ({ parsedInput: { businessType, orgId, mode }, ctx: { supabase } }) => {
    if (orgId === 'demo-org') {
      redirect(`/dashboard/pages/build/${businessType}?mode=${mode}`)
    }

    const { cookies } = await import('next/headers')
    if ((await cookies()).get('demo_mode')?.value === '1') {
      revalidatePath('/dashboard/pages')
      return { success: true }
    }

    if (mode === 'primary') {
      await supabase
        .from('organizations')
        .update({ business_type: businessType })
        .eq('id', orgId)
    }

    redirect(`/dashboard/pages/build/${businessType}?mode=${mode}`)
  })

// ─── Page Creation ─────────────────────────────────────────────────────────────

export const createCustomPage = authActionClient
  .schema(zfd.formData({
    title: zfd.text(),
    slug: zfd.text(),
    content: zfd.text(z.string().optional()),
    location_id: zfd.text(),
    template_type: zfd.text(z.string().default('info')),
    is_primary: zfd.checkbox(),
    billing_enabled: zfd.checkbox(),
    billing_mode: zfd.text(z.string().default('standard_checkout')),
    payment_mode: zfd.text(z.string().default('full')),
    deposit_percentage: zfd.numeric(z.number().optional()),
    business_type_preset: zfd.text(z.string().optional())
  }))
  .action(async ({ parsedInput, ctx: { supabase, user } }) => {
    const {
      title, slug, content, location_id, template_type, is_primary,
      billing_enabled, billing_mode, payment_mode, deposit_percentage, business_type_preset
    } = parsedInput

    if (location_id === 'demo-loc') {
      revalidatePath('/dashboard/pages')
      return { success: true }
    }

    const { cookies } = await import('next/headers')
    if ((await cookies()).get('demo_mode')?.value === '1') {
      revalidatePath('/dashboard/pages')
      return { success: true }
    }

    const { data: loc } = await supabase
      .from('locations')
      .select('organization_id')
      .eq('id', location_id)
      .single()
    if (!loc) throw new Error('Location not found')
    const orgId = loc.organization_id

    const { data: org } = await supabase
      .from('organizations')
      .select('subscription_tier')
      .eq('id', orgId)
      .single()

    const { count } = await supabase
      .from('location_pages')
      .select('id', { count: 'exact' })
      .eq('location_id', location_id)

    const { getFreePagesLimit } = await import('@/lib/utils/billing')
    const freeLimit = await getFreePagesLimit(org?.subscription_tier || 'lite')

    if (!is_primary && (count || 0) >= freeLimit) {
      const { getCreditCosts } = await import('@/lib/utils/settings')
      const creditCosts = await getCreditCosts() as Record<string, number>
      const pageCost = creditCosts.custom_page || 10

      const { chargeCredits } = await import('@/lib/payments/credits')
      const charge = await chargeCredits(
        orgId,
        pageCost,
        `Created Page: ${slug} (${template_type})`,
        user.id
      )
      if (!charge.success) {
        throw new Error(`Insufficient credits to create an extra page. (Cost: ${pageCost})`)
      }
    }

    if (is_primary) {
      await supabase
        .from('location_pages')
        .update({ is_primary: false })
        .eq('location_id', location_id)
        .eq('is_primary', true)
    }

    const { error } = await supabase.from('location_pages').insert({
      location_id,
      title,
      slug,
      content: content || null,
      template_type,
      is_primary,
      billing_enabled,
      billing_mode,
      payment_mode,
      deposit_percentage: deposit_percentage || null,
      business_type_preset: business_type_preset || null,
      is_published: true,
    })

    if (error) throw new Error((error as Error).message)

    revalidatePath('/dashboard/pages')
    redirect('/dashboard/pages')
  })

