'use client'

import { toast } from 'sonner';

import { useState, useTransition, useEffect, useRef } from 'react';

import { useRouter } from 'next/navigation'
import Link from 'next/link'
import type { BusinessTypePreset } from '@/lib/templates/presets'
import { createCustomPage, addPageItem, updatePageItem, deletePageItem, updateItemAvailability } from '../../actions'

interface Item {
  id?: string
  title: string
  subtitle: string
  description: string
  price_minor: number | ''
  price_display: string
  availability_status: string
  payment_mode: string
  deposit_percentage: number | ''
  item_data: Record<string, string>
}

const AVAILABILITY_OPTIONS = [
  { value: 'available', label: '✅ Available', color: 'text-emerald-400' },
  { value: 'unavailable', label: '⏸️ Unavailable', color: 'text-zinc-400' },
  { value: 'sold_out', label: '🔴 Taken / Sold Out', color: 'text-red-400' },
]

const emptyItem = (): Item => ({
  title: '',
  subtitle: '',
  description: '',
  price_minor: '',
  price_display: '',
  availability_status: 'available',
  payment_mode: 'full',
  deposit_percentage: '',
  item_data: {},
})

interface Props {
  preset: BusinessTypePreset
  businessType: string
  orgId: string
  orgName: string
  locationId: string
  locationSlug: string
  mode: string
  existingPage: Record<string, unknown> | null
  existingItems: unknown[]
  defaultTitle: string
}

export function ListingBuilderClient({
  preset,
  businessType,
  orgId,
  orgName,
  locationId,
  locationSlug,
  mode,
  existingPage,
  existingItems,
  defaultTitle,
}: Props) {
  const router = useRouter()
  const [isPending, startTransition] = useTransition()

  // Page-level state
  const [pageTitle, setPageTitle] = useState((existingPage?.title as string) || defaultTitle)
  const [slug, setSlug] = useState(
    (existingPage?.slug as string) || pageTitle.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '')
  )
  const [pageDescription, setPageDescription] = useState((existingPage?.content as string) || '')
  const [isPrimary] = useState(mode === 'primary')

  // Items state
  const [items, setItems] = useState<Item[]>(
    (existingItems as Record<string, unknown>[]).map((i) => ({
      id: i.id as string,
      title: i.title as string,
      subtitle: (i.subtitle as string) || '',
      description: (i.description as string) || '',
      price_minor: (i.price_minor as number) || '',
      price_display: (i.price_display as string) || '',
      availability_status: (i.availability_status as string) || 'available',
      payment_mode: (i.payment_mode as string) || 'full',
      deposit_percentage: (i.deposit_percentage as number) || '',
      item_data: (i.item_data as Record<string, string>) || {},
    })) || [emptyItem()]
  )
  const [editingIdx, setEditingIdx] = useState<number | null>(items.length === 0 ? 0 : null)
  const [activeSection, setActiveSection] = useState<'details' | 'listings'>('details')

  // Local state for dynamic specs in the editor
  const [newSpecKey, setNewSpecKey] = useState('')
  const [newSpecValue, setNewSpecValue] = useState('')

  const pageId = existingPage?.id as string | undefined

  function handleTitleChange(val: string) {
    setPageTitle(val)
    if (!pageId) {
      setSlug(val.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, ''))
    }
  }

  function addNewItem() {
    setItems(prev => [...prev, emptyItem()])
    setEditingIdx(items.length)
  }

  function updateItem(idx: number, field: keyof Item, value: unknown) {
    setItems(prev => prev.map((item, i) => i === idx ? { ...item, [field]: value } : item))
  }

  function addSpec(idx: number) {
    if (!newSpecKey.trim() || !newSpecValue.trim()) return
    setItems(prev => prev.map((item, i) => {
      if (i === idx) {
        return {
          ...item,
          item_data: { ...item.item_data, [newSpecKey.trim()]: newSpecValue.trim() }
        }
      }
      return item
    }))
    setNewSpecKey('')
    setNewSpecValue('')
  }

  function removeSpec(idx: number, keyToRemove: string) {
    setItems(prev => prev.map((item, i) => {
      if (i === idx) {
        const newData = { ...item.item_data }
        delete newData[keyToRemove]
        return { ...item, item_data: newData }
      }
      return item
    }))
  }

  async function handleSavePage() {
    if (!pageTitle.trim()) return

    const formData = new FormData()
    formData.set('title', pageTitle)
    formData.set('slug', slug)
    formData.set('content', pageDescription)
    formData.set('location_id', locationId)
    formData.set('template_type', 'listing')
    formData.set('is_primary', isPrimary.toString())
    formData.set('billing_enabled', 'false') 
    formData.set('billing_mode', 'standard_checkout')
    formData.set('payment_mode', 'full')
    formData.set('business_type_preset', businessType)

    if (pageId) {
      formData.set('pageId', pageId)
      // Pass required defaults for updatePage
      formData.set('billing_enabled', existingPage?.billing_enabled ? 'true' : 'false')
      formData.set('billing_mode', existingPage?.billing_mode as string || 'standard_checkout')
      formData.set('payment_mode', existingPage?.payment_mode as string || 'full')
      if (existingPage?.deposit_percentage) formData.set('deposit_percentage', existingPage.deposit_percentage.toString())
      formData.set('randomizer_enabled', existingPage?.randomizer_enabled ? 'true' : 'false')

      startTransition(async () => {
        const { updatePage } = await import('../../actions')
        const updateRes = await updatePage(formData);
        if (updateRes?.serverError || updateRes?.validationErrors) { toast.error(updateRes.serverError || 'Update failed'); return; }

        // Save items
        for (const [index, item] of items.entries()) {
          const itemFormData = new FormData()
          itemFormData.set('page_id', pageId)
          itemFormData.set('title', item.title)
          itemFormData.set('subtitle', item.subtitle)
          itemFormData.set('description', item.description)
          itemFormData.set('availability_status', item.availability_status)
          if (item.price_minor !== '') itemFormData.set('price_minor', item.price_minor.toString())
          itemFormData.set('price_display', item.price_display)
          itemFormData.set('sort_order', index.toString())
          itemFormData.set('item_data', JSON.stringify(item.item_data))

          if (item.id && !item.id.startsWith('new_')) {
            itemFormData.set('itemId', item.id)
            const itemRes = await updatePageItem(itemFormData);
            if (itemRes?.serverError || itemRes?.validationErrors) { toast.error(itemRes.serverError || 'Failed to update item'); return; }
          } else {
            await addPageItem(itemFormData)
          }
        }

        // Delete items that were removed
        const currentIds = items.map(i => i.id as string).filter(id => id && !id.startsWith('new_'))
        const originalIds = (existingItems as Record<string, unknown>[]).map(i => i.id as string)
        for (const id of originalIds) {
          if (!currentIds.includes(id)) {
            const delForm = new FormData()
            delForm.set('itemId', id)
            await deletePageItem(delForm)
          }
        }

        router.refresh()
      })
    } else {
      startTransition(async () => {
        const createRes = await createCustomPage(formData);
        if (createRes?.serverError || createRes?.validationErrors) { toast.error(createRes.serverError || 'Creation failed'); return; }
      })
    }
  }

  const publicUrl = `${process.env.NEXT_PUBLIC_SITE_URL || 'https://ourmenu.os'}/m/${locationSlug}/p/${slug}`

  return (
    <div className="min-h-screen bg-black text-white">
      {/* Top bar */}
      <div className="sticky top-0 z-20 flex items-center justify-between px-6 md:px-12 h-16 bg-black/80 backdrop-blur-xl border-b border-white/[0.05]">
        <Link href="/dashboard/pages" className="flex items-center gap-2 text-zinc-400 hover:text-white transition-colors text-sm">
          <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" />
          </svg>
          Your Pages
        </Link>
        <div className="flex items-center gap-2">
          <span className="text-[10px] font-bold uppercase tracking-widest text-blue-400 bg-blue-500/10 border border-blue-500/20 px-2 py-1 rounded-full">
            {preset.icon} {preset.label}
          </span>
        </div>
        <button
          onClick={handleSavePage}
          disabled={isPending || !pageTitle.trim()}
          className="px-5 py-2 rounded-xl bg-gradient-to-r from-violet-600 to-indigo-600 text-white text-sm font-bold hover:from-violet-500 hover:to-indigo-500 disabled:opacity-40 transition-all shadow-lg shadow-violet-900/30"
        >
          {isPending ? 'Saving…' : pageId ? 'Save Changes' : 'Publish Page'}
        </button>
      </div>

      <div className="max-w-4xl mx-auto px-6 md:px-12 py-10">
        {/* Section tabs */}
        <div className="flex gap-1 mb-8 bg-zinc-900/50 p-1 rounded-xl w-fit">
          {(['details', 'listings'] as const).map((s) => (
            <button
              key={s}
              onClick={() => setActiveSection(s)}
              className={`px-4 py-2 rounded-lg text-sm font-medium transition-all capitalize ${
                activeSection === s
                  ? 'bg-zinc-800 text-white shadow'
                  : 'text-zinc-500 hover:text-zinc-300'
              }`}
            >
              {s === 'listings' ? `${preset.icon} Listings & Portfolio` : s.charAt(0).toUpperCase() + s.slice(1)}
            </button>
          ))}
        </div>

        {/* ── DETAILS ─────────────────────────────────────────────────────── */}
        {activeSection === 'details' && (
          <div className="space-y-6">
            <div>
              <label className="block text-xs font-bold text-zinc-400 uppercase tracking-wider mb-2">Page Title</label>
              <input
                value={pageTitle}
                onChange={(e) => handleTitleChange(e.target.value)}
                placeholder={defaultTitle}
                className="w-full bg-zinc-900 border border-zinc-800 rounded-xl px-4 py-3 text-white text-lg font-semibold focus:border-violet-500 focus:outline-none transition-colors"
              />
            </div>

            {!pageId && (
              <div>
                <label className="block text-xs font-bold text-zinc-400 uppercase tracking-wider mb-2">URL Slug</label>
                <div className="flex items-center gap-2 bg-zinc-900 border border-zinc-800 rounded-xl px-4 py-3">
                  <span className="text-zinc-600 text-sm shrink-0">/m/{locationSlug}/p/</span>
                  <input
                    value={slug}
                    onChange={(e) => setSlug(e.target.value.toLowerCase().replace(/[^a-z0-9-]/g, ''))}
                    className="flex-1 bg-transparent text-white text-sm focus:outline-none"
                  />
                </div>
              </div>
            )}

            <div>
              <label className="block text-xs font-bold text-zinc-400 uppercase tracking-wider mb-2">
                Page Description <span className="text-zinc-600 font-normal">(optional)</span>
              </label>
              <textarea
                value={pageDescription}
                onChange={(e) => setPageDescription(e.target.value)}
                rows={4}
                placeholder={`Describe your portfolio, properties, or listings...`}
                className="w-full bg-zinc-900 border border-zinc-800 rounded-xl px-4 py-3 text-white text-sm focus:border-violet-500 focus:outline-none transition-colors resize-none"
              />
            </div>

            {/* Public URL preview */}
            <div className="rounded-xl border border-zinc-800 bg-zinc-900/30 p-4">
              <div className="text-xs font-bold text-zinc-500 uppercase tracking-wider mb-1">Your public link</div>
              <div className="text-sm text-blue-400 font-mono break-all">{publicUrl}</div>
            </div>

            {pageId && (
              <div className="rounded-xl border border-blue-500/20 bg-blue-500/5 p-4">
                <div className="flex gap-3">
                  <span className="text-blue-400 text-sm">ℹ️</span>
                  <div>
                    <div className="text-sm font-bold text-blue-300 mb-1">Save your listings</div>
                    <div className="text-xs text-zinc-400">
                      Be sure to save changes here to update both your Page Details and your Listings at once.
                    </div>
                  </div>
                </div>
              </div>
            )}
          </div>
        )}

        {/* ── LISTINGS ────────────────────────────────────────────────────── */}
        {activeSection === 'listings' && (
          <div className="space-y-4">
            <div className="flex items-center justify-between mb-2">
              <div>
                <h2 className="text-base font-bold text-white">Listings</h2>
                <p className="text-xs text-zinc-500 mt-0.5">Add your properties, cars, or portfolio items.</p>
              </div>
              <button
                onClick={addNewItem}
                className="flex items-center gap-2 px-4 py-2 rounded-xl bg-white/5 border border-white/10 text-sm text-zinc-300 hover:text-white hover:border-white/20 transition-all"
              >
                <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" />
                </svg>
                Add Listing
              </button>
            </div>

            {items.map((item, idx) => (
              <div key={idx} className={`rounded-2xl border transition-all ${editingIdx === idx ? 'border-violet-500/40 bg-violet-900/5' : 'border-zinc-800 bg-zinc-900/30'}`}>
                {/* Collapsed row */}
                {editingIdx !== idx ? (
                  <div
                    className="flex items-center justify-between p-4 cursor-pointer"
                    onClick={() => setEditingIdx(idx)}
                  >
                    <div className="flex items-center gap-3">
                      <div className={`w-2 h-2 rounded-full ${item.availability_status === 'available' ? 'bg-emerald-400' : 'bg-zinc-600'}`} />
                      <div>
                        <span className="text-sm font-semibold text-white">{item.title || 'Untitled Listing'}</span>
                        {item.subtitle && <span className="text-xs text-zinc-500 ml-2">{item.subtitle}</span>}
                      </div>
                    </div>
                    <div className="flex items-center gap-3">
                      {item.price_display ? (
                        <span className="text-sm font-bold text-white">{item.price_display}</span>
                      ) : item.price_minor !== '' ? (
                        <span className="text-sm font-bold text-white">
                          ₦{Number(item.price_minor / 100).toLocaleString()}
                        </span>
                      ) : null}
                      <svg className="w-4 h-4 text-zinc-500" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
                      </svg>
                    </div>
                  </div>
                ) : (
                  /* Expanded editor */
                  <div className="p-5 space-y-4">
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                      <div>
                        <label className="block text-xs font-bold text-zinc-400 uppercase tracking-wider mb-1.5">Listing Title *</label>
                        <input
                          value={item.title}
                          onChange={(e) => updateItem(idx, 'title', e.target.value)}
                          placeholder="e.g. 4 Bedroom Duplex"
                          className="w-full bg-zinc-900 border border-zinc-800 rounded-xl px-3 py-2.5 text-sm text-white focus:border-violet-500 focus:outline-none transition-colors"
                        />
                      </div>
                      <div>
                        <label className="block text-xs font-bold text-zinc-400 uppercase tracking-wider mb-1.5">
                          Subtitle / Location
                        </label>
                        <input
                          value={item.subtitle}
                          onChange={(e) => updateItem(idx, 'subtitle', e.target.value)}
                          placeholder="e.g. Lekki Phase 1"
                          className="w-full bg-zinc-900 border border-zinc-800 rounded-xl px-3 py-2.5 text-sm text-white focus:border-violet-500 focus:outline-none transition-colors"
                        />
                      </div>
                    </div>

                    <div>
                      <label className="block text-xs font-bold text-zinc-400 uppercase tracking-wider mb-1.5">Category / Grouping</label>
                      <input
                        value={item.item_data?.category || ''}
                        onChange={(e) => {
                          const val = e.target.value
                          setItems(prev => prev.map((itm, i) => i === idx ? { ...itm, item_data: { ...itm.item_data, category: val } } : itm))
                        }}
                        placeholder="e.g. For Rent, For Sale, Premium Cars"
                        className="w-full bg-zinc-900 border border-zinc-800 rounded-xl px-3 py-2.5 text-sm text-white focus:border-violet-500 focus:outline-none transition-colors"
                      />
                    </div>

                    <div>
                      <label className="block text-xs font-bold text-zinc-400 uppercase tracking-wider mb-1.5">Description</label>
                      <textarea
                        value={item.description}
                        onChange={(e) => updateItem(idx, 'description', e.target.value)}
                        rows={3}
                        placeholder="Describe the listing..."
                        className="w-full bg-zinc-900 border border-zinc-800 rounded-xl px-3 py-2.5 text-sm text-white focus:border-violet-500 focus:outline-none transition-colors resize-none"
                      />
                    </div>

                    <div className="grid grid-cols-2 sm:grid-cols-3 gap-4">
                      <div>
                        <label className="block text-xs font-bold text-zinc-400 uppercase tracking-wider mb-1.5">
                          Base Price (₦)
                        </label>
                        <div className="relative">
                          <span className="absolute left-3 top-1/2 -translate-y-1/2 text-zinc-500 text-sm">₦</span>
                          <input
                            type="number"
                            value={item.price_minor !== '' ? Number(item.price_minor) / 100 : ''}
                            onChange={(e) => updateItem(idx, 'price_minor', e.target.value ? Math.round(parseFloat(e.target.value) * 100) : '')}
                            placeholder="0.00"
                            className="w-full bg-zinc-900 border border-zinc-800 rounded-xl pl-7 pr-3 py-2.5 text-sm text-white focus:border-violet-500 focus:outline-none transition-colors"
                          />
                        </div>
                      </div>

                      <div>
                        <label className="block text-xs font-bold text-zinc-400 uppercase tracking-wider mb-1.5">Display Price (Optional)</label>
                        <input
                          value={item.price_display}
                          onChange={(e) => updateItem(idx, 'price_display', e.target.value)}
                          placeholder='e.g. "₦150m (Negotiable)"'
                          className="w-full bg-zinc-900 border border-zinc-800 rounded-xl px-3 py-2.5 text-sm text-white focus:border-violet-500 focus:outline-none transition-colors"
                        />
                      </div>

                      <div>
                        <label className="block text-xs font-bold text-zinc-400 uppercase tracking-wider mb-1.5">Status</label>
                        <select
                          value={item.availability_status}
                          onChange={(e) => updateItem(idx, 'availability_status', e.target.value)}
                          className="w-full bg-zinc-900 border border-zinc-800 rounded-xl px-3 py-2.5 text-sm text-white focus:border-violet-500 focus:outline-none transition-colors appearance-none"
                        >
                          {AVAILABILITY_OPTIONS.map(o => (
                            <option key={o.value} value={o.value}>{o.label}</option>
                          ))}
                        </select>
                      </div>
                    </div>

                    {/* DYNAMIC SPECS SECTION */}
                    <div className="pt-4 mt-4 border-t border-zinc-800">
                      <label className="block text-xs font-bold text-zinc-400 uppercase tracking-wider mb-2">
                        Specifications & Filters
                      </label>
                      <p className="text-xs text-zinc-500 mb-4">
                        Add key-value pairs (e.g. Bedrooms: 4, Property Type: Duplex). These automatically become dynamic filters on your public page.
                      </p>

                      <div className="flex flex-wrap gap-2 mb-3">
                        {Object.entries(item.item_data || {}).map(([key, value]) => (
                          <div key={key} className="flex items-center gap-2 bg-zinc-800 border border-zinc-700 px-3 py-1.5 rounded-lg text-sm text-white">
                            <span className="font-bold text-zinc-400">{key}:</span> {value}
                            <button onClick={() => removeSpec(idx, key)} className="ml-1 text-zinc-500 hover:text-red-400">✕</button>
                          </div>
                        ))}
                      </div>

                      <div className="flex gap-2">
                        <input
                          value={newSpecKey}
                          onChange={e => setNewSpecKey(e.target.value)}
                          placeholder="Key (e.g. Bedrooms)"
                          className="bg-zinc-900 border border-zinc-800 rounded-lg px-3 py-2 text-sm text-white focus:border-violet-500 focus:outline-none w-1/3"
                        />
                        <input
                          value={newSpecValue}
                          onChange={e => setNewSpecValue(e.target.value)}
                          placeholder="Value (e.g. 4)"
                          className="bg-zinc-900 border border-zinc-800 rounded-lg px-3 py-2 text-sm text-white focus:border-violet-500 focus:outline-none flex-1"
                        />
                        <button
                          onClick={() => addSpec(idx)}
                          type="button"
                          disabled={!newSpecKey.trim() || !newSpecValue.trim()}
                          className="px-4 py-2 rounded-lg bg-white/10 text-white text-sm font-medium hover:bg-white/20 disabled:opacity-50"
                        >
                          Add
                        </button>
                      </div>
                    </div>

                    {/* Item actions */}
                    <div className="flex items-center justify-between pt-4 mt-4 border-t border-zinc-800">
                      <button
                        onClick={() => {
                          setItems(prev => prev.filter((_, i) => i !== idx))
                          setEditingIdx(null)
                        }}
                        className="text-xs text-red-400 hover:text-red-300 transition-colors"
                      >
                        Remove listing
                      </button>
                      <button
                        onClick={() => setEditingIdx(null)}
                        className="px-4 py-1.5 rounded-lg bg-zinc-800 text-sm text-white hover:bg-zinc-700 transition-colors"
                      >
                        Done
                      </button>
                    </div>
                  </div>
                )}
              </div>
            ))}

            {items.length === 0 && (
              <div className="text-center py-12 text-zinc-600">
                <p className="text-sm mb-3">No listings yet.</p>
                <button
                  onClick={addNewItem}
                  className="text-violet-400 text-sm hover:text-violet-300 transition-colors"
                >
                  + Add your first listing
                </button>
              </div>
            )}

            {!pageId && items.length > 0 && (
              <div className="text-xs text-zinc-500 text-center mt-4">
                Note: Listings will be saved after you click &quot;Publish Page&quot;. You can edit them anytime.
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  )
}

'use client'

import { toast } from 'sonner';

import { useState, useTransition, useEffect, useRef } from 'react';

import { useRouter } from 'next/navigation'
import Link from 'next/link'
import type { BusinessTypePreset } from '@/lib/templates/presets'
import { createCustomPage, addPageItem, updatePageItem, deletePageItem, updateItemAvailability } from '../../actions'

interface Item {
  id?: string
  title: string
  subtitle: string
  description: string
  price_minor: number | ''
  price_display: string
  availability_status: string
  payment_mode: string
  deposit_percentage: number | ''
  item_data: Record<string, string>
}

const AVAILABILITY_OPTIONS = [
  { value: 'available', label: '✅ Available', color: 'text-emerald-400' },
  { value: 'unavailable', label: '⏸️ Unavailable', color: 'text-zinc-400' },
]

const emptyItem = (): Item => ({
  title: '',
  subtitle: '',
  description: '',
  price_minor: '',
  price_display: '',
  availability_status: 'available',
  payment_mode: 'full',
  deposit_percentage: '',
  item_data: {},
})

interface Props {
  preset: BusinessTypePreset
  businessType: string
  orgId: string
  orgName: string
  locationId: string
  locationSlug: string
  mode: string
  existingPage: Record<string, unknown> | null
  existingItems: unknown[]
  defaultTitle: string
}

export function QuoteBuilderClient({
  preset,
  businessType,
  orgId,
  orgName,
  locationId,
  locationSlug,
  mode,
  existingPage,
  existingItems,
  defaultTitle,
}: Props) {
  const router = useRouter()
  const [isPending, startTransition] = useTransition()

  // Page-level state
  const [pageTitle, setPageTitle] = useState((existingPage?.title as string) || defaultTitle)
  const [slug, setSlug] = useState(
    (existingPage?.slug as string) || pageTitle.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '')
  )
  const [pageDescription, setPageDescription] = useState((existingPage?.content as string) || '')
  const [isPrimary] = useState(mode === 'primary')

  // Items state
  const [items, setItems] = useState<Item[]>(
    (existingItems as Record<string, unknown>[]).map((i) => ({
      id: i.id as string,
      title: i.title as string,
      subtitle: (i.subtitle as string) || '',
      description: (i.description as string) || '',
      price_minor: (i.price_minor as number) || '',
      price_display: (i.price_display as string) || '',
      availability_status: (i.availability_status as string) || 'available',
      payment_mode: (i.payment_mode as string) || 'full',
      deposit_percentage: (i.deposit_percentage as number) || '',
      item_data: (i.item_data as Record<string, string>) || {},
    })) || [emptyItem()]
  )
  const [editingIdx, setEditingIdx] = useState<number | null>(items.length === 0 ? 0 : null)
  const [activeSection, setActiveSection] = useState<'details' | 'services' | 'settings'>('details')

  // Page Settings State
  const [randomizerEnabled, setRandomizerEnabled] = useState(existingPage?.randomizer_enabled as boolean || false)
  const [milestonesEnabled, setMilestonesEnabled] = useState((existingPage?.template_data as Record<string, unknown>)?.milestones_enabled as boolean || false)
  const [refundPolicy, setRefundPolicy] = useState((existingPage?.template_data as Record<string, unknown>)?.refund_policy as string || '')
  const [paymentChannels, setPaymentChannels] = useState<string[]>((existingPage?.template_data as Record<string, unknown>)?.payment_channels as string[] || ['card', 'bank_transfer', 'ussd'])

  // Socials
  const [whatsapp, setWhatsapp] = useState((existingPage?.template_data as Record<string, unknown>)?.whatsapp_number as string || '')
  const [phone, setPhone] = useState((existingPage?.template_data as Record<string, unknown>)?.phone_number as string || '')
  const [instagram, setInstagram] = useState((existingPage?.template_data as Record<string, unknown>)?.instagram_handle as string || '')
  const [twitter, setTwitter] = useState((existingPage?.template_data as Record<string, unknown>)?.x_handle as string || '')
  const [tiktok, setTiktok] = useState((existingPage?.template_data as Record<string, unknown>)?.tiktok_handle as string || '')

  const pageId = existingPage?.id as string | undefined

  function handleTitleChange(val: string) {
    setPageTitle(val)
    if (!pageId) {
      setSlug(val.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, ''))
    }
  }

  function addNewItem() {
    setItems(prev => [...prev, emptyItem()])
    setEditingIdx(items.length)
  }

  function updateItem(idx: number, field: keyof Item, value: unknown) {
    setItems(prev => prev.map((item, i) => i === idx ? { ...item, [field]: value } : item))
  }

  function updateItemData(idx: number, key: string, value: string) {
    setItems(prev => prev.map((item, i) => {
      if (i === idx) {
        return {
          ...item,
          item_data: { ...item.item_data, [key]: value }
        }
      }
      return item
    }))
  }

  async function handleSavePage() {
    if (!pageTitle.trim()) return

    const formData = new FormData()
    formData.set('title', pageTitle)
    formData.set('slug', slug)
    formData.set('content', pageDescription)
    formData.set('location_id', locationId)
    formData.set('template_type', 'quote')
    formData.set('is_primary', isPrimary.toString())
    formData.set('billing_enabled', 'false') // quotes don't checkout immediately
    formData.set('billing_mode', 'standard_checkout')
    formData.set('payment_mode', 'full')
    formData.set('business_type_preset', businessType)

    if (pageId) {
      formData.set('pageId', pageId)
      // Pass required defaults for updatePage
      formData.set('billing_enabled', existingPage?.billing_enabled ? 'true' : 'false')
      formData.set('billing_mode', existingPage?.billing_mode as string || 'standard_checkout')
      formData.set('payment_mode', existingPage?.payment_mode as string || 'full')
      if (existingPage?.deposit_percentage) formData.set('deposit_percentage', existingPage.deposit_percentage.toString())

      // Pass the updated settings
      formData.set('randomizer_enabled', randomizerEnabled ? 'true' : 'false')
      formData.set('milestones_enabled', milestonesEnabled ? 'true' : 'false')
      formData.set('hide_delivery', 'false') // not used in quote
      paymentChannels.forEach(c => formData.append('payment_channels', c))
      formData.set('refund_policy', refundPolicy)
      if (whatsapp) formData.set('whatsapp_number', whatsapp)
      if (phone) formData.set('phone_number', phone)
      if (instagram) formData.set('instagram_handle', instagram)
      if (twitter) formData.set('x_handle', twitter)
      if (tiktok) formData.set('tiktok_handle', tiktok)

      startTransition(async () => {
        const { updatePage } = await import('../../actions')
        const updateRes = await updatePage(formData);
        if (updateRes?.serverError || updateRes?.validationErrors) { toast.error(updateRes.serverError || 'Update failed'); return; }

        // Save items
        for (const [index, item] of items.entries()) {
          const itemFormData = new FormData()
          itemFormData.set('page_id', pageId)
          itemFormData.set('title', item.title)
          itemFormData.set('subtitle', item.subtitle)
          itemFormData.set('description', item.description)
          itemFormData.set('availability_status', item.availability_status)
          itemFormData.set('sort_order', index.toString())
          itemFormData.set('item_data', JSON.stringify(item.item_data))

          if (item.id && !item.id.startsWith('new_')) {
            itemFormData.set('itemId', item.id)
            const itemRes = await updatePageItem(itemFormData);
            if (itemRes?.serverError || itemRes?.validationErrors) { toast.error(itemRes.serverError || 'Failed to update item'); return; }
          } else {
            await addPageItem(itemFormData)
          }
        }

        // Delete items that were removed
        const currentIds = items.map(i => i.id as string).filter(id => id && !id.startsWith('new_'))
        const originalIds = (existingItems as Record<string, unknown>[]).map(i => i.id as string)
        for (const id of originalIds) {
          if (!currentIds.includes(id)) {
            const delForm = new FormData()
            delForm.set('itemId', id)
            await deletePageItem(delForm)
          }
        }

        router.refresh()
      })
    } else {
      startTransition(async () => {
        const createRes = await createCustomPage(formData);
        if (createRes?.serverError || createRes?.validationErrors) { toast.error(createRes.serverError || 'Creation failed'); return; }
        // Note: In our current setup, createCustomPage might just redirect.
        // For a full fix, createCustomPage should return the page ID, but since it redirects,
        // we might not be able to save items immediately if it hard redirects. 
        // We will assume the user has to click "Save Services" later, or we just rely on the redirect.
      })
    }
  }

  const publicUrl = `${process.env.NEXT_PUBLIC_SITE_URL || 'https://ourmenu.os'}/m/${locationSlug}/p/${slug}`

  return (
    <div className="min-h-screen bg-black text-white">
      {/* Top bar */}
      <div className="sticky top-0 z-20 flex items-center justify-between px-6 md:px-12 h-16 bg-black/80 backdrop-blur-xl border-b border-white/[0.05]">
        <Link href="/dashboard/pages" className="flex items-center gap-2 text-zinc-400 hover:text-white transition-colors text-sm">
          <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" />
          </svg>
          Your Pages
        </Link>
        <div className="flex items-center gap-2">
          <span className="text-[10px] font-bold uppercase tracking-widest text-blue-400 bg-blue-500/10 border border-blue-500/20 px-2 py-1 rounded-full">
            {preset.icon} {preset.label}
          </span>
        </div>
        <button
          onClick={handleSavePage}
          disabled={isPending || !pageTitle.trim()}
          className="px-5 py-2 rounded-xl bg-gradient-to-r from-violet-600 to-indigo-600 text-white text-sm font-bold hover:from-violet-500 hover:to-indigo-500 disabled:opacity-40 transition-all shadow-lg shadow-violet-900/30"
        >
          {isPending ? 'Saving…' : pageId ? 'Save Changes' : 'Publish Page'}
        </button>
      </div>

      <div className="max-w-4xl mx-auto px-6 md:px-12 py-10">
        {/* Section tabs */}
        <div className="flex gap-1 mb-8 bg-zinc-900/50 p-1 rounded-xl w-fit">
          {(['details', 'services', 'settings'] as const).map((s) => (
            <button
              key={s}
              onClick={() => setActiveSection(s)}
              className={`px-4 py-2 rounded-lg text-sm font-medium transition-all capitalize ${
                activeSection === s
                  ? 'bg-zinc-800 text-white shadow'
                  : 'text-zinc-500 hover:text-zinc-300'
              }`}
            >
              {s === 'services' ? `${preset.icon} Services & Pricing` : s === 'settings' ? 'Add-ons & Settings' : s.charAt(0).toUpperCase() + s.slice(1)}
            </button>
          ))}
        </div>


        {/* ── DETAILS ─────────────────────────────────────────────────────── */}
        {activeSection === 'details' && (
          <div className="space-y-6">
            <div>
              <label className="block text-xs font-bold text-zinc-400 uppercase tracking-wider mb-2">Page Title</label>
              <input
                value={pageTitle}
                onChange={(e) => handleTitleChange(e.target.value)}
                placeholder={defaultTitle}
                className="w-full bg-zinc-900 border border-zinc-800 rounded-xl px-4 py-3 text-white text-lg font-semibold focus:border-violet-500 focus:outline-none transition-colors"
              />
            </div>

            {!pageId && (
              <div>
                <label className="block text-xs font-bold text-zinc-400 uppercase tracking-wider mb-2">URL Slug</label>
                <div className="flex items-center gap-2 bg-zinc-900 border border-zinc-800 rounded-xl px-4 py-3">
                  <span className="text-zinc-600 text-sm shrink-0">/m/{locationSlug}/p/</span>
                  <input
                    value={slug}
                    onChange={(e) => setSlug(e.target.value.toLowerCase().replace(/[^a-z0-9-]/g, ''))}
                    className="flex-1 bg-transparent text-white text-sm focus:outline-none"
                  />
                </div>
              </div>
            )}

            <div>
              <label className="block text-xs font-bold text-zinc-400 uppercase tracking-wider mb-2">
                Page Description <span className="text-zinc-600 font-normal">(optional — shown to customers)</span>
              </label>
              <textarea
                value={pageDescription}
                onChange={(e) => setPageDescription(e.target.value)}
                rows={4}
                placeholder={`Tell customers about your ${preset.label.toLowerCase()} — what to expect, process, etc.`}
                className="w-full bg-zinc-900 border border-zinc-800 rounded-xl px-4 py-3 text-white text-sm focus:border-violet-500 focus:outline-none transition-colors resize-none"
              />
            </div>

            {/* Public URL preview */}
            <div className="rounded-xl border border-zinc-800 bg-zinc-900/30 p-4">
              <div className="text-xs font-bold text-zinc-500 uppercase tracking-wider mb-1">Your public link</div>
              <div className="text-sm text-blue-400 font-mono break-all">{publicUrl}</div>
            </div>

            {pageId && (
              <div className="rounded-xl border border-blue-500/20 bg-blue-500/5 p-4">
                <div className="flex gap-3">
                  <span className="text-blue-400 text-sm">ℹ️</span>
                  <div>
                    <div className="text-sm font-bold text-blue-300 mb-1">Save your services</div>
                    <div className="text-xs text-zinc-400">
                      Be sure to save changes here to update both your Page Details and your Services & Pricing items at once.
                    </div>
                  </div>
                </div>
              </div>
            )}
          </div>
        )}

        {/* ── SERVICES ────────────────────────────────────────────────────── */}
        {activeSection === 'services' && (
          <div className="space-y-4">
            <div className="flex items-center justify-between mb-2">
              <div>
                <h2 className="text-base font-bold text-white">Services & Pricing</h2>
                <p className="text-xs text-zinc-500 mt-0.5">List your offerings. Customers can add these to their quote request.</p>
              </div>
              <button
                onClick={addNewItem}
                className="flex items-center gap-2 px-4 py-2 rounded-xl bg-white/5 border border-white/10 text-sm text-zinc-300 hover:text-white hover:border-white/20 transition-all"
              >
                <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" />
                </svg>
                Add Service
              </button>
            </div>

            {items.map((item, idx) => (
              <div key={idx} className={`rounded-2xl border transition-all ${editingIdx === idx ? 'border-violet-500/40 bg-violet-900/5' : 'border-zinc-800 bg-zinc-900/30'}`}>
                {/* Collapsed row */}
                {editingIdx !== idx ? (
                  <div
                    className="flex items-center justify-between p-4 cursor-pointer"
                    onClick={() => setEditingIdx(idx)}
                  >
                    <div className="flex items-center gap-3">
                      <div className={`w-2 h-2 rounded-full ${item.availability_status === 'available' ? 'bg-emerald-400' : 'bg-zinc-600'}`} />
                      <div>
                        <span className="text-sm font-semibold text-white">{item.title || 'Untitled Service'}</span>
                        {item.item_data?.price_range && <span className="text-xs text-zinc-500 ml-2">{item.item_data.price_range}</span>}
                      </div>
                    </div>
                    <div className="flex items-center gap-3">
                      <svg className="w-4 h-4 text-zinc-500" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
                      </svg>
                    </div>
                  </div>
                ) : (
                  /* Expanded editor */
                  <div className="p-5 space-y-4">
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                      <div>
                        <label className="block text-xs font-bold text-zinc-400 uppercase tracking-wider mb-1.5">Service Name *</label>
                        <input
                          value={item.title}
                          onChange={(e) => updateItem(idx, 'title', e.target.value)}
                          placeholder="e.g. Website Development"
                          className="w-full bg-zinc-900 border border-zinc-800 rounded-xl px-3 py-2.5 text-sm text-white focus:border-violet-500 focus:outline-none transition-colors"
                        />
                      </div>
                      <div>
                        <label className="block text-xs font-bold text-zinc-400 uppercase tracking-wider mb-1.5">
                          Unit of Measurement
                        </label>
                        <input
                          value={item.item_data?.unit || ''}
                          onChange={(e) => updateItemData(idx, 'unit', e.target.value)}
                          placeholder="e.g. per page, per hour, flat rate"
                          className="w-full bg-zinc-900 border border-zinc-800 rounded-xl px-3 py-2.5 text-sm text-white focus:border-violet-500 focus:outline-none transition-colors"
                        />
                      </div>
                    </div>

                    <div>
                      <label className="block text-xs font-bold text-zinc-400 uppercase tracking-wider mb-1.5">Category</label>
                      <input
                        value={item.item_data?.category || ''}
                        onChange={(e) => updateItemData(idx, 'category', e.target.value)}
                        placeholder="e.g. Design, Development, Add-ons"
                        className="w-full bg-zinc-900 border border-zinc-800 rounded-xl px-3 py-2.5 text-sm text-white focus:border-violet-500 focus:outline-none transition-colors"
                      />
                    </div>

                    <div>
                      <label className="block text-xs font-bold text-zinc-400 uppercase tracking-wider mb-1.5">Description</label>
                      <textarea
                        value={item.description}
                        onChange={(e) => updateItem(idx, 'description', e.target.value)}
                        rows={3}
                        placeholder="What's included in this service?"
                        className="w-full bg-zinc-900 border border-zinc-800 rounded-xl px-3 py-2.5 text-sm text-white focus:border-violet-500 focus:outline-none transition-colors resize-none"
                      />
                    </div>

                    <div className="grid grid-cols-2 sm:grid-cols-3 gap-4">
                      <div>
                        <label className="block text-xs font-bold text-zinc-400 uppercase tracking-wider mb-1.5">
                          Price Range / Estimate
                        </label>
                        <input
                          value={item.item_data?.price_range || ''}
                          onChange={(e) => updateItemData(idx, 'price_range', e.target.value)}
                          placeholder="e.g. ₦50k - ₦100k"
                          className="w-full bg-zinc-900 border border-zinc-800 rounded-xl px-3 py-2.5 text-sm text-white focus:border-violet-500 focus:outline-none transition-colors"
                        />
                      </div>

                      <div>
                        <label className="block text-xs font-bold text-zinc-400 uppercase tracking-wider mb-1.5">Turnaround Time</label>
                        <input
                          value={item.item_data?.turnaround || ''}
                          onChange={(e) => updateItemData(idx, 'turnaround', e.target.value)}
                          placeholder='e.g. "2-3 weeks"'
                          className="w-full bg-zinc-900 border border-zinc-800 rounded-xl px-3 py-2.5 text-sm text-white focus:border-violet-500 focus:outline-none transition-colors"
                        />
                      </div>

                      <div>
                        <label className="block text-xs font-bold text-zinc-400 uppercase tracking-wider mb-1.5">Status</label>
                        <select
                          value={item.availability_status}
                          onChange={(e) => updateItem(idx, 'availability_status', e.target.value)}
                          className="w-full bg-zinc-900 border border-zinc-800 rounded-xl px-3 py-2.5 text-sm text-white focus:border-violet-500 focus:outline-none transition-colors appearance-none"
                        >
                          {AVAILABILITY_OPTIONS.map(o => (
                            <option key={o.value} value={o.value}>{o.label}</option>
                          ))}
                        </select>
                      </div>
                    </div>

                    {/* Item actions */}
                    <div className="flex items-center justify-between pt-2 border-t border-zinc-800">
                      <button
                        onClick={() => {
                          setItems(prev => prev.filter((_, i) => i !== idx))
                          setEditingIdx(null)
                        }}
                        className="text-xs text-red-400 hover:text-red-300 transition-colors"
                      >
                        Remove service
                      </button>
                      <button
                        onClick={() => setEditingIdx(null)}
                        className="px-4 py-1.5 rounded-lg bg-zinc-800 text-sm text-white hover:bg-zinc-700 transition-colors"
                      >
                        Done
                      </button>
                    </div>
                  </div>
                )}
              </div>
            ))}

            {items.length === 0 && (
              <div className="text-center py-12 text-zinc-600">
                <p className="text-sm mb-3">No services listed yet.</p>
                <button
                  onClick={addNewItem}
                  className="text-violet-400 text-sm hover:text-violet-300 transition-colors"
                >
                  + Add your first service
                </button>
              </div>
            )}

            {!pageId && items.length > 0 && (
              <div className="text-xs text-zinc-500 text-center mt-4">
                Note: Services will be saved after you click &quot;Publish Page&quot;. You can edit them anytime.
              </div>
            )}
          </div>
        )}

        {/* ── SETTINGS ────────────────────────────────────────────────────── */}
        {activeSection === 'settings' && (
          <div className="space-y-6">
            <h2 className="text-base font-bold text-white mb-4">Add-ons & Global Settings</h2>

            {/* Roulette Addon */}
            <div className="flex items-center justify-between p-4 bg-zinc-900 border border-zinc-800 rounded-xl">
              <div>
                <p className="text-sm font-bold text-white">Payment Roulette Add-on</p>
                <p className="text-xs text-zinc-400 mt-0.5">Enable the &quot;Surprise Me" spinning wheel for customers who can&apos;t decide.</p>
              </div>
              <label className="relative inline-flex items-center cursor-pointer">
                <input type="checkbox" checked={randomizerEnabled} onChange={e => setRandomizerEnabled(e.target.checked)} className="sr-only peer" />
                <div className="w-11 h-6 bg-zinc-700 peer-focus:outline-none rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-purple-500"></div>
              </label>
            </div>

            {/* Milestones Addon */}
            <div className="flex items-center justify-between p-4 bg-zinc-900 border border-zinc-800 rounded-xl">
              <div>
                <p className="text-sm font-bold text-white">Milestone Billing (Add-on)</p>
                <p className="text-xs text-zinc-400 mt-0.5">Allow splitting invoices into custom payment milestones (e.g., 30% upfront, 70% completion).</p>
              </div>
              <label className="relative inline-flex items-center cursor-pointer">
                <input type="checkbox" checked={milestonesEnabled} onChange={e => setMilestonesEnabled(e.target.checked)} className="sr-only peer" />
                <div className="w-11 h-6 bg-zinc-700 peer-focus:outline-none rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-purple-500"></div>
              </label>
            </div>

            <div className="space-y-4 pt-4 border-t border-zinc-800">
              <div>
                <label className="block text-xs font-bold text-zinc-400 uppercase tracking-wider mb-2">Allowed Payment Methods</label>
                <div className="flex gap-4">
                  {['card', 'bank_transfer', 'ussd'].map((method) => (
                    <label key={method} className="flex items-center gap-2 text-sm text-white cursor-pointer">
                      <input 
                        type="checkbox" 
                        checked={paymentChannels.includes(method)} 
                        onChange={e => {
                          if (e.target.checked) setPaymentChannels(prev => [...prev, method])
                          else setPaymentChannels(prev => prev.filter(c => c !== method))
                        }}
                        className="rounded bg-zinc-900 border-zinc-800 text-purple-500 focus:ring-purple-500" 
                      />
                      {method.replace('_', ' ').replace(/\b\w/g, l => l.toUpperCase())}
                    </label>
                  ))}
                </div>
              </div>

              <div>
                <label className="block text-xs font-bold text-zinc-400 uppercase tracking-wider mb-2">Cancellation & Refund Policy</label>
                <textarea 
                  value={refundPolicy}
                  onChange={e => setRefundPolicy(e.target.value)}
                  placeholder="e.g. Deposits are non-refundable if cancelled within 48 hours." 
                  className="w-full bg-zinc-900 border border-zinc-800 rounded-lg px-3 py-2 text-sm text-white h-20 resize-none" 
                />
              </div>
            </div>

            <div className="space-y-4 pt-4 border-t border-zinc-800">
              <h3 className="text-sm font-bold text-white">Social & Contact Links</h3>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div>
                  <label className="block text-xs text-zinc-400 mb-1">WhatsApp Number</label>
                  <input value={whatsapp} onChange={e => setWhatsapp(e.target.value)} placeholder="e.g. +2348012345678" className="w-full bg-zinc-900 border border-zinc-800 rounded-lg px-3 py-2 text-sm text-white" />
                </div>
                <div>
                  <label className="block text-xs text-zinc-400 mb-1">Phone Number</label>
                  <input value={phone} onChange={e => setPhone(e.target.value)} placeholder="e.g. +2348012345678" className="w-full bg-zinc-900 border border-zinc-800 rounded-lg px-3 py-2 text-sm text-white" />
                </div>
                <div>
                  <label className="block text-xs text-zinc-400 mb-1">Instagram Handle</label>
                  <input value={instagram} onChange={e => setInstagram(e.target.value)} placeholder="e.g. @ourmenu" className="w-full bg-zinc-900 border border-zinc-800 rounded-lg px-3 py-2 text-sm text-white" />
                </div>
                <div>
                  <label className="block text-xs text-zinc-400 mb-1">X (Twitter) Handle</label>
                  <input value={twitter} onChange={e => setTwitter(e.target.value)} placeholder="e.g. @ourmenu" className="w-full bg-zinc-900 border border-zinc-800 rounded-lg px-3 py-2 text-sm text-white" />
                </div>
                <div>
                  <label className="block text-xs text-zinc-400 mb-1">TikTok Handle</label>
                  <input value={tiktok} onChange={e => setTiktok(e.target.value)} placeholder="e.g. @ourmenu" className="w-full bg-zinc-900 border border-zinc-800 rounded-lg px-3 py-2 text-sm text-white" />
                </div>
              </div>
            </div>

          </div>
        )}
      </div>
    </div>
  )
}

'use client'

import { toast } from 'sonner';

import { useState, useTransition, useEffect, useRef } from 'react';

import { useRouter } from 'next/navigation'
import Link from 'next/link'
import type { BusinessTypePreset } from '@/lib/templates/presets'
import { createCustomPage, addPageItem, updatePageItem, deletePageItem, updateItemAvailability } from '../../actions'

interface Item {
  id?: string
  title: string
  subtitle: string
  description: string
  price_minor: number | ''
  price_display: string
  availability_status: string
  payment_mode: string
  deposit_percentage: number | ''
  item_data: Record<string, string>
}

const AVAILABILITY_OPTIONS = [
  { value: 'available', label: '✅ Available', color: 'text-emerald-400' },
  { value: 'unavailable', label: '⏸️ Unavailable', color: 'text-zinc-400' },
]

const TIER_CATEGORIES = [
  { value: 'basic', label: 'Basic Tier' },
  { value: 'standard', label: 'Standard Tier' },
  { value: 'premium', label: 'Premium Tier' },
  { value: 'addon', label: 'Add-on Service' },
]

const emptyItem = (): Item => ({
  title: '',
  subtitle: '',
  description: '',
  price_minor: '',
  price_display: '',
  availability_status: 'available',
  payment_mode: 'full',
  deposit_percentage: '',
  item_data: { category: 'standard' },
})

interface Props {
  preset: BusinessTypePreset
  businessType: string
  orgId: string
  orgName: string
  locationId: string
  locationSlug: string
  mode: string
  existingPage: Record<string, unknown> | null
  existingItems: unknown[]
  defaultTitle: string
}

export function RateCardBuilderClient({
  preset,
  businessType,
  orgId,
  orgName,
  locationId,
  locationSlug,
  mode,
  existingPage,
  existingItems,
  defaultTitle,
}: Props) {
  const router = useRouter()
  const [isPending, startTransition] = useTransition()

  // Page-level state
  const [pageTitle, setPageTitle] = useState((existingPage?.title as string) || defaultTitle)
  const [slug, setSlug] = useState(
    (existingPage?.slug as string) || pageTitle.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '')
  )
  const [pageDescription, setPageDescription] = useState((existingPage?.content as string) || '')
  const [isPrimary] = useState(mode === 'primary')

  // Payment settings for the page
  const [billingEnabled, setBillingEnabled] = useState((existingPage?.billing_enabled as boolean) ?? preset.billing_enabled)
  const [paymentMode, setPaymentMode] = useState((existingPage?.payment_mode as string) || preset.payment_mode)
  const [depositPct, setDepositPct] = useState<number | ''>((existingPage?.deposit_percentage as number) || preset.deposit_percentage || '')

  // Items state
  const [items, setItems] = useState<Item[]>(
    (existingItems as Record<string, unknown>[]).map((i) => ({
      id: i.id as string,
      title: i.title as string,
      subtitle: (i.subtitle as string) || '',
      description: (i.description as string) || '',
      price_minor: (i.price_minor as number) || '',
      price_display: (i.price_display as string) || '',
      availability_status: (i.availability_status as string) || 'available',
      payment_mode: (i.payment_mode as string) || 'full',
      deposit_percentage: (i.deposit_percentage as number) || '',
      item_data: (i.item_data as Record<string, string>) || { category: 'standard' },
    })) || [emptyItem()]
  )
  const [editingIdx, setEditingIdx] = useState<number | null>(items.length === 0 ? 0 : null)
  const [activeSection, setActiveSection] = useState<'details' | 'services' | 'settings'>('details')

  const pageId = existingPage?.id as string | undefined

  function handleTitleChange(val: string) {
    setPageTitle(val)
    if (!pageId) {
      setSlug(val.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, ''))
    }
  }

  function addNewItem() {
    setItems(prev => [...prev, emptyItem()])
    setEditingIdx(items.length)
  }

  function updateItem(idx: number, field: keyof Item, value: unknown) {
    setItems(prev => prev.map((item, i) => i === idx ? { ...item, [field]: value } : item))
  }

  function updateItemData(idx: number, key: string, value: string) {
    setItems(prev => prev.map((item, i) => {
      if (i === idx) {
        return {
          ...item,
          item_data: { ...item.item_data, [key]: value }
        }
      }
      return item
    }))
  }

  async function handleSavePage() {
    if (!pageTitle.trim()) return

    const formData = new FormData()
    formData.set('title', pageTitle)
    formData.set('slug', slug)
    formData.set('content', pageDescription)
    formData.set('location_id', locationId)
    formData.set('template_type', 'rate_card')
    formData.set('is_primary', isPrimary.toString())
    formData.set('billing_enabled', billingEnabled.toString())
    formData.set('billing_mode', 'standard_checkout')
    formData.set('payment_mode', paymentMode)
    if (depositPct) formData.set('deposit_percentage', depositPct.toString())
    formData.set('business_type_preset', businessType)

    if (pageId) {
      formData.set('pageId', pageId)
      // Pass required defaults for updatePage
      formData.set('randomizer_enabled', existingPage?.randomizer_enabled ? 'true' : 'false')

      startTransition(async () => {
        const { updatePage } = await import('../../actions')
        const updateRes = await updatePage(formData);
        if (updateRes?.serverError || updateRes?.validationErrors) { toast.error(updateRes.serverError || 'Update failed'); return; }

        // Save items
        for (const [index, item] of items.entries()) {
          const itemFormData = new FormData()
          itemFormData.set('page_id', pageId)
          itemFormData.set('title', item.title)
          itemFormData.set('subtitle', item.subtitle)
          itemFormData.set('description', item.description)
          itemFormData.set('availability_status', item.availability_status)
          if (item.price_minor !== '') itemFormData.set('price_minor', item.price_minor.toString())
          itemFormData.set('price_display', item.price_display)
          itemFormData.set('payment_mode', item.payment_mode)
          if (item.deposit_percentage) itemFormData.set('deposit_percentage', item.deposit_percentage.toString())
          itemFormData.set('sort_order', index.toString())
          itemFormData.set('item_data', JSON.stringify(item.item_data))

          if (item.id && !item.id.startsWith('new_')) {
            itemFormData.set('itemId', item.id)
            const itemRes = await updatePageItem(itemFormData);
            if (itemRes?.serverError || itemRes?.validationErrors) { toast.error(itemRes.serverError || 'Failed to update item'); return; }
          } else {
            await addPageItem(itemFormData)
          }
        }

        // Delete items that were removed
        const currentIds = items.map(i => i.id as string).filter(id => id && !id.startsWith('new_'))
        const originalIds = (existingItems as Record<string, unknown>[]).map(i => i.id as string)
        for (const id of originalIds) {
          if (!currentIds.includes(id)) {
            const delForm = new FormData()
            delForm.set('itemId', id)
            await deletePageItem(delForm)
          }
        }

        router.refresh()
      })
    } else {
      startTransition(async () => {
        const createRes = await createCustomPage(formData);
        if (createRes?.serverError || createRes?.validationErrors) { toast.error(createRes.serverError || 'Creation failed'); return; }
      })
    }
  }

  const publicUrl = `${process.env.NEXT_PUBLIC_SITE_URL || 'https://ourmenu.os'}/m/${locationSlug}/p/${slug}`

  return (
    <div className="min-h-screen bg-black text-white">
      {/* Top bar */}
      <div className="sticky top-0 z-20 flex items-center justify-between px-6 md:px-12 h-16 bg-black/80 backdrop-blur-xl border-b border-white/[0.05]">
        <Link href="/dashboard/pages" className="flex items-center gap-2 text-zinc-400 hover:text-white transition-colors text-sm">
          <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" />
          </svg>
          Your Pages
        </Link>
        <div className="flex items-center gap-2">
          <span className="text-[10px] font-bold uppercase tracking-widest text-blue-400 bg-blue-500/10 border border-blue-500/20 px-2 py-1 rounded-full">
            {preset.icon} {preset.label}
          </span>
        </div>
        <button
          onClick={handleSavePage}
          disabled={isPending || !pageTitle.trim()}
          className="px-5 py-2 rounded-xl bg-gradient-to-r from-violet-600 to-indigo-600 text-white text-sm font-bold hover:from-violet-500 hover:to-indigo-500 disabled:opacity-40 transition-all shadow-lg shadow-violet-900/30"
        >
          {isPending ? 'Saving…' : pageId ? 'Save Changes' : 'Publish Page'}
        </button>
      </div>

      <div className="max-w-4xl mx-auto px-6 md:px-12 py-10">
        {/* Section tabs */}
        <div className="flex gap-1 mb-8 bg-zinc-900/50 p-1 rounded-xl w-fit">
          {(['details', 'services', 'settings'] as const).map((s) => (
            <button
              key={s}
              onClick={() => setActiveSection(s)}
              className={`px-4 py-2 rounded-lg text-sm font-medium transition-all capitalize ${
                activeSection === s
                  ? 'bg-zinc-800 text-white shadow'
                  : 'text-zinc-500 hover:text-zinc-300'
              }`}
            >
              {s === 'services' ? `${preset.icon} Rate Card` : s.charAt(0).toUpperCase() + s.slice(1)}
            </button>
          ))}
        </div>

        {/* ── DETAILS ─────────────────────────────────────────────────────── */}
        {activeSection === 'details' && (
          <div className="space-y-6">
            <div>
              <label className="block text-xs font-bold text-zinc-400 uppercase tracking-wider mb-2">Page Title</label>
              <input
                value={pageTitle}
                onChange={(e) => handleTitleChange(e.target.value)}
                placeholder={defaultTitle}
                className="w-full bg-zinc-900 border border-zinc-800 rounded-xl px-4 py-3 text-white text-lg font-semibold focus:border-violet-500 focus:outline-none transition-colors"
              />
            </div>

            {!pageId && (
              <div>
                <label className="block text-xs font-bold text-zinc-400 uppercase tracking-wider mb-2">URL Slug</label>
                <div className="flex items-center gap-2 bg-zinc-900 border border-zinc-800 rounded-xl px-4 py-3">
                  <span className="text-zinc-600 text-sm shrink-0">/m/{locationSlug}/p/</span>
                  <input
                    value={slug}
                    onChange={(e) => setSlug(e.target.value.toLowerCase().replace(/[^a-z0-9-]/g, ''))}
                    className="flex-1 bg-transparent text-white text-sm focus:outline-none"
                  />
                </div>
              </div>
            )}

            <div>
              <label className="block text-xs font-bold text-zinc-400 uppercase tracking-wider mb-2">
                Bio / About <span className="text-zinc-600 font-normal">(optional)</span>
              </label>
              <textarea
                value={pageDescription}
                onChange={(e) => setPageDescription(e.target.value)}
                rows={4}
                placeholder={`Describe your freelance services, agency, or expertise...`}
                className="w-full bg-zinc-900 border border-zinc-800 rounded-xl px-4 py-3 text-white text-sm focus:border-violet-500 focus:outline-none transition-colors resize-none"
              />
            </div>

            {/* Public URL preview */}
            <div className="rounded-xl border border-zinc-800 bg-zinc-900/30 p-4">
              <div className="text-xs font-bold text-zinc-500 uppercase tracking-wider mb-1">Your public link</div>
              <div className="text-sm text-blue-400 font-mono break-all">{publicUrl}</div>
            </div>
          </div>
        )}

        {/* ── SERVICES / RATE CARD ────────────────────────────────────────── */}
        {activeSection === 'services' && (
          <div className="space-y-4">
            <div className="flex items-center justify-between mb-2">
              <div>
                <h2 className="text-base font-bold text-white">Rate Card Items</h2>
                <p className="text-xs text-zinc-500 mt-0.5">Build your tiers (Basic, Standard, Premium) and Add-ons.</p>
              </div>
              <button
                onClick={addNewItem}
                className="flex items-center gap-2 px-4 py-2 rounded-xl bg-white/5 border border-white/10 text-sm text-zinc-300 hover:text-white hover:border-white/20 transition-all"
              >
                <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" />
                </svg>
                Add Package
              </button>
            </div>

            {items.map((item, idx) => (
              <div key={idx} className={`rounded-2xl border transition-all ${editingIdx === idx ? 'border-violet-500/40 bg-violet-900/5' : 'border-zinc-800 bg-zinc-900/30'}`}>
                {/* Collapsed row */}
                {editingIdx !== idx ? (
                  <div
                    className="flex items-center justify-between p-4 cursor-pointer"
                    onClick={() => setEditingIdx(idx)}
                  >
                    <div className="flex items-center gap-3">
                      <div className={`w-2 h-2 rounded-full ${item.availability_status === 'available' ? 'bg-emerald-400' : 'bg-zinc-600'}`} />
                      <div>
                        <div className="flex items-center gap-2">
                          <span className="text-sm font-semibold text-white">{item.title || 'Untitled Package'}</span>
                          <span className="text-[10px] bg-zinc-800 text-zinc-400 px-2 py-0.5 rounded-full capitalize">{item.item_data?.category || 'standard'}</span>
                        </div>
                        {item.subtitle && <span className="text-xs text-zinc-500 mt-0.5 block">{item.subtitle}</span>}
                      </div>
                    </div>
                    <div className="flex items-center gap-3">
                      {item.price_display ? (
                        <span className="text-sm font-bold text-white">{item.price_display}</span>
                      ) : item.price_minor !== '' ? (
                        <span className="text-sm font-bold text-white">
                          ₦{Number(item.price_minor / 100).toLocaleString()}
                        </span>
                      ) : null}
                      <svg className="w-4 h-4 text-zinc-500" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
                      </svg>
                    </div>
                  </div>
                ) : (
                  /* Expanded editor */
                  <div className="p-5 space-y-4">
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                      <div>
                        <label className="block text-xs font-bold text-zinc-400 uppercase tracking-wider mb-1.5">Package Title *</label>
                        <input
                          value={item.title}
                          onChange={(e) => updateItem(idx, 'title', e.target.value)}
                          placeholder="e.g. Logo Design"
                          className="w-full bg-zinc-900 border border-zinc-800 rounded-xl px-3 py-2.5 text-sm text-white focus:border-violet-500 focus:outline-none transition-colors"
                        />
                      </div>
                      <div>
                        <label className="block text-xs font-bold text-zinc-400 uppercase tracking-wider mb-1.5">
                          Tier Category
                        </label>
                        <input
                          list="tier-categories"
                          value={item.item_data?.category || ''}
                          onChange={(e) => updateItemData(idx, 'category', e.target.value)}
                          placeholder="e.g. basic, custom, maintenance"
                          className="w-full bg-zinc-900 border border-zinc-800 rounded-xl px-3 py-2.5 text-sm text-white focus:border-violet-500 focus:outline-none transition-colors"
                        />
                        <datalist id="tier-categories">
                          {TIER_CATEGORIES.map(o => (
                            <option key={o.value} value={o.value}>{o.label}</option>
                          ))}
                        </datalist>
                      </div>
                    </div>

                    <div>
                      <label className="block text-xs font-bold text-zinc-400 uppercase tracking-wider mb-1.5">Subtitle / Short Note</label>
                      <input
                        value={item.subtitle}
                        onChange={(e) => updateItem(idx, 'subtitle', e.target.value)}
                        placeholder="e.g. Best for startups"
                        className="w-full bg-zinc-900 border border-zinc-800 rounded-xl px-3 py-2.5 text-sm text-white focus:border-violet-500 focus:outline-none transition-colors"
                      />
                    </div>

                    <div>
                      <label className="block text-xs font-bold text-zinc-400 uppercase tracking-wider mb-1.5">Description</label>
                      <textarea
                        value={item.description}
                        onChange={(e) => updateItem(idx, 'description', e.target.value)}
                        rows={2}
                        placeholder="What is this package about?"
                        className="w-full bg-zinc-900 border border-zinc-800 rounded-xl px-3 py-2.5 text-sm text-white focus:border-violet-500 focus:outline-none transition-colors resize-none"
                      />
                    </div>

                    <div>
                      <label className="block text-xs font-bold text-zinc-400 uppercase tracking-wider mb-1.5">Features Included</label>
                      <p className="text-xs text-zinc-500 mb-2">Separate each feature with a comma. These will render as checkmarks.</p>
                      <textarea
                        value={item.item_data?.includes || ''}
                        onChange={(e) => updateItemData(idx, 'includes', e.target.value)}
                        rows={2}
                        placeholder="e.g. 2 concepts, 3 revisions, source files"
                        className="w-full bg-zinc-900 border border-zinc-800 rounded-xl px-3 py-2.5 text-sm text-white focus:border-violet-500 focus:outline-none transition-colors resize-none"
                      />
                    </div>

                    <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
                      <div>
                        <label className="block text-xs font-bold text-zinc-400 uppercase tracking-wider mb-1.5">
                          Base Price (₦)
                        </label>
                        <div className="relative">
                          <span className="absolute left-3 top-1/2 -translate-y-1/2 text-zinc-500 text-sm">₦</span>
                          <input
                            type="number"
                            value={item.price_minor !== '' ? Number(item.price_minor) / 100 : ''}
                            onChange={(e) => updateItem(idx, 'price_minor', e.target.value ? Math.round(parseFloat(e.target.value) * 100) : '')}
                            placeholder="0.00"
                            className="w-full bg-zinc-900 border border-zinc-800 rounded-xl pl-7 pr-3 py-2.5 text-sm text-white focus:border-violet-500 focus:outline-none transition-colors"
                          />
                        </div>
                      </div>

                      <div>
                        <label className="block text-xs font-bold text-zinc-400 uppercase tracking-wider mb-1.5">Display Price</label>
                        <input
                          value={item.price_display}
                          onChange={(e) => updateItem(idx, 'price_display', e.target.value)}
                          placeholder='e.g. "₦150k"'
                          className="w-full bg-zinc-900 border border-zinc-800 rounded-xl px-3 py-2.5 text-sm text-white focus:border-violet-500 focus:outline-none transition-colors"
                        />
                      </div>

                      <div>
                        <label className="block text-xs font-bold text-zinc-400 uppercase tracking-wider mb-1.5">Turnaround</label>
                        <input
                          value={item.item_data?.turnaround || ''}
                          onChange={(e) => updateItemData(idx, 'turnaround', e.target.value)}
                          placeholder='e.g. "3-5 days"'
                          className="w-full bg-zinc-900 border border-zinc-800 rounded-xl px-3 py-2.5 text-sm text-white focus:border-violet-500 focus:outline-none transition-colors"
                        />
                      </div>

                      <div>
                        <label className="block text-xs font-bold text-zinc-400 uppercase tracking-wider mb-1.5">Status</label>
                        <select
                          value={item.availability_status}
                          onChange={(e) => updateItem(idx, 'availability_status', e.target.value)}
                          className="w-full bg-zinc-900 border border-zinc-800 rounded-xl px-3 py-2.5 text-sm text-white focus:border-violet-500 focus:outline-none transition-colors appearance-none"
                        >
                          {AVAILABILITY_OPTIONS.map(o => (
                            <option key={o.value} value={o.value}>{o.label}</option>
                          ))}
                        </select>
                      </div>
                    </div>

                    {/* Payment settings per package */}
                    {billingEnabled && (
                      <div className="pt-2 border-t border-zinc-800">
                        <div className="flex items-center gap-4 mb-3">
                          <label className="text-xs font-bold text-zinc-400 uppercase tracking-wider">Payment Mode</label>
                          <div className="flex gap-2">
                            {(['full', 'deposit'] as const).map(m => (
                              <button
                                key={m}
                                type="button"
                                onClick={() => updateItem(idx, 'payment_mode', m)}
                                className={`px-3 py-1 rounded-lg text-xs font-bold transition-all ${
                                  item.payment_mode === m
                                    ? 'bg-violet-500/20 text-violet-300 border border-violet-500/30'
                                    : 'bg-zinc-800 text-zinc-400 border border-zinc-700 hover:border-zinc-600'
                                }`}
                              >
                                {m === 'full' ? 'Full Payment' : 'Deposit'}
                              </button>
                            ))}
                          </div>
                        </div>
                        {item.payment_mode === 'deposit' && (
                          <div className="flex items-center gap-3">
                            <label className="text-xs text-zinc-500">Deposit %</label>
                            <input
                              type="number"
                              min={1}
                              max={100}
                              value={item.deposit_percentage}
                              onChange={(e) => updateItem(idx, 'deposit_percentage', parseInt(e.target.value))}
                              placeholder="50"
                              className="w-20 bg-zinc-900 border border-zinc-800 rounded-lg px-3 py-1.5 text-sm text-white focus:border-violet-500 focus:outline-none"
                            />
                            <span className="text-xs text-zinc-500">% charged upfront</span>
                          </div>
                        )}
                      </div>
                    )}

                    {/* Item actions */}
                    <div className="flex items-center justify-between pt-4 mt-4 border-t border-zinc-800">
                      <button
                        onClick={() => {
                          setItems(prev => prev.filter((_, i) => i !== idx))
                          setEditingIdx(null)
                        }}
                        className="text-xs text-red-400 hover:text-red-300 transition-colors"
                      >
                        Remove package
                      </button>
                      <button
                        onClick={() => setEditingIdx(null)}
                        className="px-4 py-1.5 rounded-lg bg-zinc-800 text-sm text-white hover:bg-zinc-700 transition-colors"
                      >
                        Done
                      </button>
                    </div>
                  </div>
                )}
              </div>
            ))}

            {items.length === 0 && (
              <div className="text-center py-12 text-zinc-600">
                <p className="text-sm mb-3">No packages yet.</p>
                <button
                  onClick={addNewItem}
                  className="text-violet-400 text-sm hover:text-violet-300 transition-colors"
                >
                  + Add your first package
                </button>
              </div>
            )}

            {!pageId && items.length > 0 && (
              <div className="text-xs text-zinc-500 text-center mt-4">
                Note: Packages will be saved after you click &quot;Publish Page&quot;. You can edit them anytime.
              </div>
            )}
          </div>
        )}

        {/* ── SETTINGS ────────────────────────────────────────────────────── */}
        {activeSection === 'settings' && (
          <div className="space-y-6">
            {/* Billing toggle */}
            <div className="rounded-2xl border border-zinc-800 bg-zinc-900/30 p-5">
              <div className="flex items-center justify-between mb-4">
                <div>
                  <h3 className="text-sm font-bold text-white">Require Payments Before Starting</h3>
                  <p className="text-xs text-zinc-500 mt-0.5">
                    Process deposits or full payments for project requests via Paystack.
                  </p>
                </div>
                <button
                  onClick={() => setBillingEnabled(b => !b)}
                  className={`w-12 h-6 rounded-full transition-all relative ${billingEnabled ? 'bg-violet-600' : 'bg-zinc-700'}`}
                >
                  <span className={`absolute top-0.5 left-0.5 w-5 h-5 rounded-full bg-white transition-all ${billingEnabled ? 'translate-x-6' : ''}`} />
                </button>
              </div>

              {billingEnabled && (
                <div className="space-y-4 pt-4 border-t border-zinc-800">
                  <div>
                    <label className="block text-xs font-bold text-zinc-400 uppercase tracking-wider mb-2">Default Payment Mode</label>
                    <div className="flex gap-2">
                      {(['full', 'deposit'] as const).map(m => (
                        <button
                          key={m}
                          type="button"
                          onClick={() => setPaymentMode(m)}
                          className={`flex-1 py-2.5 rounded-xl text-sm font-bold transition-all border ${
                            paymentMode === m
                              ? 'bg-violet-500/15 text-violet-300 border-violet-500/30'
                              : 'bg-zinc-900 text-zinc-400 border-zinc-700 hover:border-zinc-600'
                          }`}
                        >
                          {m === 'full' ? '💳 Full Payment' : '💰 Deposit First'}
                        </button>
                      ))}
                    </div>
                  </div>

                  {paymentMode === 'deposit' && (
                    <div>
                      <label className="block text-xs font-bold text-zinc-400 uppercase tracking-wider mb-2">Default Deposit %</label>
                      <div className="flex items-center gap-3">
                        <input
                          type="range"
                          min={5}
                          max={100}
                          step={5}
                          value={typeof depositPct === 'number' ? depositPct : 50}
                          onChange={(e) => setDepositPct(parseInt(e.target.value))}
                          className="flex-1 accent-violet-500"
                        />
                        <span className="text-lg font-bold text-white w-12 text-right">
                          {typeof depositPct === 'number' ? depositPct : 50}%
                        </span>
                      </div>
                      <p className="text-xs text-zinc-600 mt-1">
                        Clients pay {typeof depositPct === 'number' ? depositPct : 50}% to start the project. (Can be overridden per package)
                      </p>
                    </div>
                  )}
                </div>
              )}
            </div>
          </div>
        )}

      </div>
    </div>
  )
}

import { createClient } from '@/lib/supabase/server'
import { redirect } from 'next/navigation'
import { Tier } from '@/lib/utils/billing'
import { togglePageStatus, deletePage } from './actions'
import { ActionForm } from '@/components/ActionForm'
import Link from 'next/link'
import Image from 'next/image'

import { BUSINESS_TYPE_PRESETS } from '@/lib/templates/presets'
import { ShareButton } from '@/components/ShareButton'

export default async function PagesManager() {
  const supabase = await createClient()
  const { data: userData } = await supabase.auth.getUser()
  const user = userData?.user

  if (!user) {
    redirect('/login')
  }

  const userId = user.id

  let org: { id: string; subscription_tier: string; purchased_credits: number; monthly_free_credits_used: number; business_type: string | null } | null = null
  let role = 'viewer'
  let locData: { id: string; slug: string } | null = null
  let pages: {
    id: string; title: string; slug: string; is_published: boolean;
    template_type: string; is_primary: boolean; created_at: string;
    business_type_preset?: string
  }[] = []

  const { data: member } = await supabase
    .from('organization_members')
    .select('role, organizations(id, subscription_tier, purchased_credits, monthly_free_credits_used, business_type)')
    .eq('user_id', userId)
    .single()

  if (member && member.organizations) {
    org = member.organizations as unknown as typeof org
    role = member.role
  } else {
    const { data } = await supabase
      .from('organizations')
      .select('id, subscription_tier, purchased_credits, monthly_free_credits_used, business_type')
      .eq('created_by', userId)
      .single()
    org = data

    role = 'owner'
  }

  const { data: locDataResult } = await supabase
    .from('locations')
    .select('id, slug')
    .eq('organization_id', org?.id || '')
    .single()
  locData = locDataResult

  if (locData) {
    const { data: pagesData } = await supabase
      .from('location_pages')
      .select('id, title, slug, is_published, template_type, is_primary, created_at, business_type_preset')
      .eq('location_id', locData.id)
      .order('is_primary', { ascending: false })
      .order('created_at', { ascending: false })

    pages = (pagesData || []) as typeof pages
  }

  if (!org || !locData) {
    return <div className="p-8 text-zinc-500">Please create an organization and a location first.</div>
  }

  // If no pages yet → redirect to the business type wizard (primary setup)
  if (pages.length === 0) {
    redirect('/dashboard/pages/setup?mode=primary')
  }

  const { getFreePagesLimit } = await import('@/lib/utils/billing')
  const freeLimit = await getFreePagesLimit((org.subscription_tier as Tier) || 'lite')
  const { getCreditCosts } = await import('@/lib/utils/settings')
  const creditCosts = await getCreditCosts() as Record<string, number>
  const pageCost = creditCosts.custom_page || 10

  const currentCount = pages.length
  const isOverLimit = currentCount >= freeLimit
  
  const creditsRemaining = (org.purchased_credits || 0) + Math.max(0, (
    org.subscription_tier === 'pro' ? 50 :
    org.subscription_tier === 'enterprise' ? 200 : 0
  ) - (org.monthly_free_credits_used || 0))

  const baseUrl = process.env.NEXT_PUBLIC_SITE_URL || 'https://ourmenuos.online'

  return (
    <div className="max-w-5xl">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between mb-8 gap-4">
        <div>
          <h1 className="text-2xl font-bold text-white">Your Pages</h1>
          <p className="text-sm text-zinc-500 mt-1">
            {currentCount} of {freeLimit} free pages used
            {isOverLimit && <span className="text-amber-400 ml-2">· Extra pages cost {pageCost} credits each</span>}
          </p>
        </div>
        <Link
          href="/dashboard/pages/setup?mode=new"
          className="flex items-center gap-2 px-5 py-2.5 rounded-xl bg-gradient-to-r from-violet-600 to-indigo-600 text-white text-sm font-bold hover:from-violet-500 hover:to-indigo-500 transition-all shadow-lg shadow-violet-900/30"
        >
          <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" />
          </svg>
          Add Page
        </Link>
      </div>

      {/* Pages list */}
      <div className="space-y-3">
        {pages.map((page) => {
          const fullUrl = `${baseUrl}/m/${locData!.slug}/p/${page.slug}`
          const qrImageUrl = `https://api.qrserver.com/v1/create-qr-code/?size=150x150&data=${encodeURIComponent(fullUrl)}&color=ffffff&bgcolor=09090b`
  
          const preset = page.template_type !== 'info' && page.template_type !== 'custom'
            ? Object.values(BUSINESS_TYPE_PRESETS).find(p => p.template_type === page.template_type)
            : null

          return (
            <div
              key={page.id}
              className={`flex items-center justify-between rounded-2xl border p-5 transition-all ${
                page.is_primary
                  ? 'border-violet-500/30 bg-violet-900/10'
                  : 'border-zinc-800 bg-zinc-900/40'
              }`}
            >
              <div className="flex items-center gap-5">
                {/* QR */}
                <div className="bg-zinc-950 p-1.5 rounded-lg border border-zinc-800 shrink-0">
                  { }
                  <Image src={qrImageUrl} alt="QR Code" width={56} height={56} className="w-14 h-14 rounded-md" crossOrigin="anonymous" />
                </div>

                <div>
                  <div className="flex items-center gap-2 mb-1">
                    <h3 className="text-base font-bold text-white">{page.title}</h3>
                    {page.is_primary && (
                      <span className="text-[10px] font-bold px-1.5 py-0.5 rounded-full bg-violet-500/20 text-violet-400 border border-violet-500/30 uppercase tracking-wider">
                        Primary
                      </span>
                    )}
                    <span className={`text-[10px] font-bold px-1.5 py-0.5 rounded-full uppercase tracking-wider ${templateBadgeClasses(page.template_type)}`}>
                      {templateTypeLabel(page.template_type)}
                    </span>
                  </div>

                  <Link
                    href={`/m/${locData!.slug}/p/${page.slug}?preview=true`}
                    target="_blank"
                    className="text-xs text-blue-400 hover:underline flex items-center gap-1"
                  >
                    {baseUrl.replace('https://', '')}/m/{locData!.slug}/p/{page.slug}
                    <svg className="w-3 h-3" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14" />
                    </svg>
                  </Link>
                </div>
              </div>

              {/* Actions */}
              <div className="flex items-center gap-2 shrink-0">
                {/* Share button */}
                <ShareButton
                  url={fullUrl}
                  title={`Check out ${page.title}`}
                  description={`View our live ${templateTypeLabel(page.template_type).toLowerCase()} at Our Venue.`}
                  className="p-2 rounded-lg text-zinc-500 hover:text-violet-400 hover:bg-violet-500/10 transition-colors"
                >
                  <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8.684 13.342C8.886 12.938 9 12.482 9 12c0-.482-.114-.938-.316-1.342m0 2.684a3 3 0 110-2.684m0 2.684l6.632 3.316m-6.632-6l6.632-3.316m0 0a3 3 0 105.367-2.684 3 3 0 00-5.367 2.684zm0 9.316a3 3 0 105.368 2.684 3 3 0 00-5.368-2.684z" />
                  </svg>
                </ShareButton>

                {/* Edit button */}
                <Link
                  href={page.business_type_preset ? `/dashboard/pages/build/${page.business_type_preset}?pageId=${page.id}` : `/dashboard/pages/${page.id}/edit`}
                  className="px-4 py-2 rounded-xl text-xs font-bold bg-white/5 hover:bg-white/10 transition-colors border border-white/10 flex items-center gap-2"
                >
                  Edit Page
                  <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z" />
                  </svg>
                </Link>

                {/* Publish/Unpublish */}
                <ActionForm action={togglePageStatus}>
                  <input type="hidden" name="pageId" value={page.id} />
                  <input type="hidden" name="currentStatus" value={page.is_published.toString()} />
                  <button
                    type="submit"
                    className={`px-3 py-1.5 rounded-lg text-xs font-medium border transition-colors ${
                      page.is_published
                        ? 'border-green-500/30 bg-green-500/10 text-green-400 hover:bg-green-500/20'
                        : 'border-zinc-700 bg-zinc-800 text-zinc-400 hover:bg-zinc-700'
                    }`}
                  >
                    {page.is_published ? 'Live' : 'Hidden'}
                  </button>
                </ActionForm>

                {/* Delete */}
                <ActionForm action={deletePage}>
                  <input type="hidden" name="pageId" value={page.id} />
                  <button
                    type="submit"
                    className="p-2 rounded-lg text-zinc-600 hover:text-red-400 hover:bg-red-500/10 transition-colors"
                    title="Delete"
                  >
                    <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
                    </svg>
                  </button>
                </ActionForm>
              </div>
            </div>
          )
        })}
      </div>
    </div>
  )
}

function templateTypeLabel(type: string): string {
  const labels: Record<string, string> = {
    catalog: 'Catalog',
    booking: 'Bookings',
    listing: 'Listings',
    rate_card: 'Rate Card',
    info: 'Info',
    custom: 'Custom',
  }
  return labels[type] ?? type
}

function templateBadgeClasses(type: string): string {
  const classes: Record<string, string> = {
    catalog: 'bg-violet-500/10 text-violet-400 border border-violet-500/20',
    booking: 'bg-blue-500/10 text-blue-400 border border-blue-500/20',
    listing: 'bg-amber-500/10 text-amber-400 border border-amber-500/20',
    rate_card: 'bg-pink-500/10 text-pink-400 border border-pink-500/20',
    info: 'bg-zinc-700/50 text-zinc-400 border border-zinc-700',
    custom: 'bg-zinc-700/50 text-zinc-400 border border-zinc-700',
  }
  return classes[type] ?? 'bg-zinc-700/50 text-zinc-400 border border-zinc-700'
}

'use server'

import { revalidatePath } from 'next/cache'
import { z } from 'zod'
import { zfd } from 'zod-form-data'
import { authActionClient } from '@/lib/safe-action'

export const generateQrBatch = authActionClient
  .schema(zfd.formData({
    organization_id: zfd.text(z.string().min(1)),
    location_id: zfd.text(z.string().uuid()),
    quantity: zfd.numeric(z.number().min(1).max(100)),
  }))
  .action(async ({ parsedInput: { organization_id: orgId, location_id: locationId, quantity }, ctx: { supabase, user } }) => {
    const { cookies } = await import('next/headers')
    const cookieStore = await cookies()
    const isDemo = cookieStore.get('demo_mode')?.value === '1'

    if (isDemo && orgId === 'demo-org') {
      if (quantity > 1) throw new Error('Demo mode is limited to generating 1 QR code at a time.')
      // In Demo Mode, allow 1 generation just to demonstrate the UI
      return { success: true }
    }

    // Fetch the location slug
    const { data: loc, error: locError } = await supabase
      .from('locations')
      .select('slug')
      .eq('id', locationId)
      .single()

    if (locError || !loc) {
      throw new Error('Location not found')
    }

    const { data: org } = await supabase
      .from('organizations')
      .select('subscription_tier')
      .eq('id', orgId)
      .single()

    const { count } = await supabase
      .from('qr_codes')
      .select('id', { count: 'exact' })
      .eq('organization_id', orgId)

    const { getFreeQrLimit } = await import('@/lib/utils/billing')
    const freeLimit = await getFreeQrLimit(org?.subscription_tier || 'lite')

    const currentCount = count || 0
    const totalAfterGeneration = currentCount + quantity

    if (totalAfterGeneration > freeLimit) {
      const excess = totalAfterGeneration - Math.max(currentCount, freeLimit)
      if (excess > 0) {
        const { getCreditCosts } = await import('@/lib/utils/settings')
        const creditCosts = await getCreditCosts() as Record<string, number>
        const qrCost = creditCosts.qr_code || 1
        const totalCost = excess * qrCost

        const { chargeCredits } = await import('@/lib/payments/credits')
        const charge = await chargeCredits(
          orgId,
          totalCost,
          `Generated ${excess} extra QR code(s)`,
          user.id
        )
        if (!charge.success) {
          throw new Error(`Insufficient credits to generate extra QR codes. You need ${totalCost} credits for the extra ${excess} codes. Buy a credit pack or upgrade your plan.`)
        }
      }
    }

    // Generate generic QR codes


    const qrCodes = Array.from({ length: quantity }).map((__, _i) => {
      return {
        organization_id: orgId,
        location_id: locationId,
        label: `Generic QR`,
        destination_path: `/m/${loc.slug}`,
        table_identifier: null,
        is_active: true
      }
    })

    const { error } = await supabase.from('qr_codes').insert(qrCodes)

    if (error) {
      throw new Error((error as Error).message)
    }

    revalidatePath('/dashboard/qr')
    return { success: true }
  })

export const deleteQrCode = authActionClient
  .schema(z.object({
    qrId: z.string().min(1)
  }))
  .action(async ({ parsedInput: { qrId }, ctx: { supabase } }) => {
    const { cookies } = await import('next/headers')
    const cookieStore = await cookies()
    if (cookieStore.get('demo_mode')?.value === '1' && qrId.startsWith('qr-')) {
      return { success: true }
    }

    const { error } = await supabase.from('qr_codes').delete().eq('id', qrId)

    if (error) throw new Error((error as Error).message)

    revalidatePath('/dashboard/qr')
    return { success: true }
  })

export const assignQrTable = authActionClient
  .schema(z.object({
    qrId: z.string().min(1),
    tableIdentifier: z.string().nullable().optional()
  }))
  .action(async ({ parsedInput: { qrId, tableIdentifier }, ctx: { supabase } }) => {
    const { cookies } = await import('next/headers')
    const cookieStore = await cookies()
    if (cookieStore.get('demo_mode')?.value === '1' && qrId.startsWith('qr-')) {
      return { success: true }
    }

    const { error } = await supabase
      .from('qr_codes')
      .update({ table_identifier: tableIdentifier || null })
      .eq('id', qrId)

    if (error) throw new Error((error as Error).message)

    revalidatePath('/dashboard/qr')
    return { success: true }
  })

