"use client";



import { useState, useRef, useEffect } from "react";
import { toast } from "sonner";
import { DynamicQR } from "@/components/qr/DynamicQR";
import { updateQrConfig } from "./actions";
import { Download, Loader2, Save } from "lucide-react";
import { Database } from "@/lib/supabase/types";

type Location = Database["public"]["Tables"]["locations"]["Row"] & {
  qr_color?: string | null;
  qr_text?: string | null;
  logo_url?: string | null;
};

function getLuminance(hex: string) {
  let r = 0, g = 0, b = 0;
  if (hex.length === 4) {
    r = parseInt(hex[1] + hex[1], 16);
    g = parseInt(hex[2] + hex[2], 16);
    b = parseInt(hex[3] + hex[3], 16);
  } else if (hex.length === 7) {
    r = parseInt(hex.substring(1, 3), 16);
    g = parseInt(hex.substring(3, 5), 16);
    b = parseInt(hex.substring(5, 7), 16);
  } else {
    return 0;
  }

  const [rs, gs, bs] = [r, g, b].map(c => {
    c = c / 255;
    return c <= 0.03928 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4);
  });
  return 0.2126 * rs + 0.7152 * gs + 0.0722 * bs;
}

function getContrast(hex1: string, hex2: string) {
  const lum1 = getLuminance(hex1);
  const lum2 = getLuminance(hex2);
  const brightest = Math.max(lum1, lum2);
  const darkest = Math.min(lum1, lum2);
  return (brightest + 0.05) / (darkest + 0.05);
}

export function QrSettingsClient({ location }: { location: Location }) {
  const [color, setColor] = useState(location.qr_color || location.theme_color || "#0f7b55");
  const [text, setText] = useState(location.qr_text || location.name.substring(0, 2).toUpperCase());
  const [logoUrl, setLogoUrl] = useState(location.logo_url || "");
  const [isSaving, setIsSaving] = useState(false);
  const svgRef = useRef<HTMLDivElement>(null);

  const [portalUrl, setPortalUrl] = useState(`https://ourmenuos.online/m/${location.slug}`);

  useEffect(() => {

    setPortalUrl(`${window.location.origin}/m/${location.slug}`);
  }, [location.slug]);

  const handleSave = async () => {
    setIsSaving(true);

    if (logoUrl) {
      try {
        await new Promise((resolve, reject) => {
          const img = new Image();
          img.onload = resolve;
          img.onerror = reject;
          img.src = logoUrl;
        });

      } catch (e) {
        toast.error("Invalid Logo URL. The image could not be loaded.");
        setIsSaving(false);
        return;
      }
    }

    try {
      const res = await updateQrConfig({
        locationId: location.id, 
        config: {
          qr_text: text,
          qr_color: color,
          logo_url: logoUrl,
        }
      });
      if (res?.serverError || res?.validationErrors) throw new Error(res?.serverError || 'Failed to save');
      toast.success("QR settings saved.");
    } catch (e: unknown) {
      toast.error("Failed to save: " + (e as Error).message);
    } finally {
      setIsSaving(false);
    }
  };

  const handleDownloadPNG = async () => {
    if (!svgRef.current) return;
    const originalSvg = svgRef.current.querySelector("svg");
    if (!originalSvg) return;

    // Clone the SVG to avoid mutating the DOM
    const svgElement = originalSvg.cloneNode(true) as SVGSVGElement;

    // Convert <image href="..."> to base64 to avoid tainted canvas errors
    const imageTags = svgElement.querySelectorAll("image");
    for (const img of imageTags) {
      const href = img.getAttribute("href");
      if (href && href.startsWith("http")) {
        try {
          const response = await fetch(href);
          const blob = await response.blob();
          const base64 = await new Promise<string>((resolve) => {
            const reader = new FileReader();
            reader.onloadend = () => resolve(reader.result as string);
            reader.readAsDataURL(blob);
          });
          img.setAttribute("href", base64);
        } catch (e) {
          console.error("Failed to fetch image for base64 conversion. Export might fail or omit the image.", e);
        }
      }
    }

    const svgData = new XMLSerializer().serializeToString(svgElement);
    const canvas = document.createElement("canvas");
    // Generate 4K (2048x2048)
    canvas.width = 2048;
    canvas.height = 2048;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const img = new Image();
    const svgBlob = new Blob([svgData], { type: "image/svg+xml;charset=utf-8" });
    const url = URL.createObjectURL(svgBlob);

    img.onload = () => {
      ctx.drawImage(img, 0, 0, 2048, 2048);
      URL.revokeObjectURL(url);

      try {
        const pngUrl = canvas.toDataURL("image/png");
        const a = document.createElement("a");
        a.href = pngUrl;
        a.download = `${location.slug}-qr.png`;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
      } catch (e) {
        console.error(e);
        toast.error("Failed to export PNG. Cross-origin image issue. Please use SVG download.");
      }
    };
    img.src = url;
  };

  const handleDownloadSVG = () => {
    if (!svgRef.current) return;
    const svgElement = svgRef.current.querySelector("svg");
    if (!svgElement) return;

    const svgData = new XMLSerializer().serializeToString(svgElement);
    const blob = new Blob([svgData], { type: "image/svg+xml;charset=utf-8" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `${location.slug}-qr.svg`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
  };

  return (
    <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
      <div className="space-y-6">
        <div className="rounded-xl border border-zinc-800 bg-zinc-900/50 overflow-hidden">
          <div className="p-6 border-b border-zinc-800/50">
            <h3 className="text-lg font-semibold text-white">Configuration</h3>
            <p className="text-sm text-zinc-400">Customize the look of your ecosystem QR.</p>
          </div>
          <div className="p-6 space-y-4">
            <div className="space-y-2">
              <label htmlFor="color" className="text-sm font-medium text-zinc-300">Theme Color</label>
              <div className="flex gap-2">
                <input 
                  id="color" 
                  type="color" 
                  value={color} 
                  onChange={(e) => setColor(e.target.value)} 
                  className="w-16 p-1 h-10 rounded border border-zinc-700 bg-zinc-800"
                />
                <input 
                  type="text" 
                  value={color} 
                  onChange={(e) => setColor(e.target.value)} 
                  className="flex-1 rounded-lg border border-zinc-700 bg-zinc-800/50 px-4 text-white focus:border-blue-500 focus:ring-1 focus:ring-blue-500"
                />
              </div>
              {getContrast(color || "#0f7b55", "#ffffff") < 2.5 && (
                <div className="mt-2 text-xs text-amber-400 bg-amber-400/10 p-2 rounded border border-amber-400/20 flex items-start gap-2">
                  <span className="text-lg leading-none">⚠️</span>
                  <span>This color is very light. The white QR dots may not have enough contrast to scan reliably. Consider a darker shade.</span>
                </div>
              )}
            </div>

            <div className="space-y-2">
              <label htmlFor="text" className="text-sm font-medium text-zinc-300">Center Text (Max 2 chars)</label>
              <input 
                id="text" 
                maxLength={2} 
                value={text} 
                onChange={(e) => setText(e.target.value)} 
                placeholder="OM"
                className="w-full rounded-lg border border-zinc-700 bg-zinc-800/50 px-4 py-2 text-white focus:border-blue-500 focus:ring-1 focus:ring-blue-500"
              />
              <p className="text-xs text-zinc-500">Used if no logo URL is provided.</p>
            </div>

            <div className="space-y-2">
              <label htmlFor="logo" className="text-sm font-medium text-zinc-300">Center Logo URL (Optional)</label>
              <input 
                id="logo" 
                type="url" 
                value={logoUrl} 
                onChange={(e) => setLogoUrl(e.target.value)} 
                placeholder="https://..."
                className="w-full rounded-lg border border-zinc-700 bg-zinc-800/50 px-4 py-2 text-white focus:border-blue-500 focus:ring-1 focus:ring-blue-500"
              />
              <p className="text-xs text-zinc-500">Overrides center text if provided.</p>
            </div>

            <button onClick={handleSave} disabled={isSaving} className="w-full mt-4 flex justify-center py-2 px-4 border border-transparent rounded-lg shadow-sm text-sm font-medium text-white bg-blue-600 hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500 disabled:opacity-50">
              {isSaving ? <Loader2 className="w-4 h-4 mr-2 animate-spin" /> : <Save className="w-4 h-4 mr-2" />}
              Save Configuration
            </button>
          </div>
        </div>
      </div>

      <div>
        <div className="flex flex-col items-center p-8 bg-zinc-900/50 rounded-xl border border-zinc-800">
          <div ref={svgRef} className="bg-white p-4 rounded-xl shadow-sm border" style={{ width: 340, height: 340 }}>
            <DynamicQR 
              value={portalUrl} 
              color={color} 
              centerText={text} 
              logoUrl={logoUrl || undefined} 
              size={1024} // Internal render size, scaled by CSS
            />
          </div>
          <p className="text-sm font-medium text-zinc-400 mt-6 mb-4">
            Destination: <span className="text-white">{portalUrl}</span>
          </p>
          <div className="flex gap-4 w-full mt-4">
            <button className="flex-1 flex justify-center py-2 px-4 border border-zinc-700 rounded-lg shadow-sm text-sm font-medium text-white bg-zinc-800 hover:bg-zinc-700" onClick={handleDownloadSVG}>
              <Download className="w-4 h-4 mr-2" />
              SVG
            </button>
            <button className="flex-1 flex justify-center py-2 px-4 border border-transparent rounded-lg shadow-sm text-sm font-medium text-zinc-900 bg-white hover:bg-zinc-100" onClick={handleDownloadPNG}>
              <Download className="w-4 h-4 mr-2" />
              High-Res PNG
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

'use server'

import { createClient } from '@/lib/supabase/server'
import { revalidatePath } from 'next/cache'
import { authActionClient } from '@/lib/safe-action'
import { z } from 'zod'
import { zfd } from 'zod-form-data'

export const clockIn = authActionClient
  .schema(z.object({ locationId: z.string() }))
  .action(async ({ parsedInput: { locationId }, ctx: { user } }) => {
    const supabase = await createClient()

    // Check if already clocked in at ANY location
    const { data: activeShifts } = await supabase
      .from('staff_shifts')
      .select('id, location_id')
      .eq('user_id', user.id)
      .eq('status', 'active')

    if (activeShifts && activeShifts.length > 0) {
      // If they are clocked into the exact same location, return success.
      if (activeShifts.some(shift => shift.location_id === locationId)) {
        return { success: true }
      }
      throw new Error('You are currently clocked in at another location. Please clock out there first.')
    }

    const { error } = await supabase
      .from('staff_shifts')
      .insert({
        location_id: locationId,
        user_id: user.id,
        status: 'active'
      })

    if (error) {
      console.error('Clock in error:', error)
      throw new Error('Failed to clock in.')
    }

    revalidatePath('/dashboard', 'layout')
    return { success: true }
  })

export const clockOut = authActionClient
  .schema(z.object({ shiftId: z.string() }))
  .action(async ({ parsedInput: { shiftId }, ctx: { user } }) => {
    const supabase = await createClient()

    // Get shift start time to calculate total_hours
    const { data: shift, error: fetchError } = await supabase
      .from('staff_shifts')
      .select('clock_in_time')
      .eq('id', shiftId)
      .single()

    if (fetchError || !shift) {
      throw new Error('Shift not found')
    }

    const clockInTime = new Date(shift.clock_in_time).getTime()
    const clockOutTime = Date.now()
    const hours = (clockOutTime - clockInTime) / (1000 * 60 * 60)

    const { error } = await supabase
      .from('staff_shifts')
      .update({
        status: 'completed',
        clock_out_time: new Date(clockOutTime).toISOString(),
        total_hours: parseFloat(hours.toFixed(2))
      })
      .eq('id', shiftId)
      .eq('user_id', user.id) // Security check

    if (error) {
      console.error('Clock out error:', error)
      throw new Error('Failed to clock out.')
    }

    revalidatePath('/dashboard', 'layout')
    return { success: true }
  })

import { ReactNode } from 'react'
import { createClient } from '@/lib/supabase/server'
import ClientLayout, { InitialDashboardData, NavItem } from './client-layout'
import { cookies } from 'next/headers'
import {
  LayoutDashboard, ClipboardList, BarChart3, BookOpen,
  FileText, Settings, Users, QrCode, TrendingUp, MessageSquare
} from 'lucide-react'

export default async function DashboardLayout({ children }: { children: ReactNode }) {
  const supabase = await createClient()
  const { data: userData } = await supabase.auth.getUser()
  const cookieStore = await cookies()

  let orgName = ''
  let isOwnerOrManager = true
  const userEmail = userData?.user?.email || ''
  let credits: number | null = null
  let locations: unknown[] = []
  let activeLocationId = ''
  let locationSlug = ''
  const baseNavItems: NavItem[] = [
    { href: '/dashboard', label: 'Overview', icon: LayoutDashboard as unknown, exact: true },
  ]
  const dynamicNavItems: NavItem[] = [...baseNavItems]

  if (userData?.user) {
    const { data: member } = await supabase
      .from('organization_members')
      .select('role, organizations(id, name, subscription_tier, purchased_credits, monthly_free_credits_used)')
      .eq('user_id', userData.user.id)
      .single()

    if (member && (member.organizations as unknown)?.name) {
      orgName = (member.organizations as unknown).name
      isOwnerOrManager = ['owner', 'manager'].includes(member.role)
      const orgData = member.organizations as unknown
      const planLimits: Record<string, number> = { lite: 10, pro: 50, enterprise: 200 }
      const availableFree = (planLimits[orgData.subscription_tier] || 0) - (orgData.monthly_free_credits_used || 0)
      const cb = Math.max(0, availableFree) + (orgData.purchased_credits || 0)
      if (!isNaN(cb)) credits = cb

      const orgId = orgData.id
      if (orgId) {
        const { data: locs } = await supabase
          .from('locations')
          .select('*')
          .eq('organization_id', orgId)

        if (locs && locs.length > 0) {
          locations = locs
          
          const savedId = cookieStore.get('ourmenu_active_location_id')?.value
          const activeLoc = locs.find((l: unknown) => l.id === savedId) || locs[0]
          
          activeLocationId = activeLoc.id
          locationSlug = activeLoc.slug

          // Fetch templates
          const { data: pages } = await supabase
            .from('location_pages')
            .select('template_type')
            .eq('location_id', activeLoc.id)
            .eq('is_published', true)

          const templates = new Set<string>()
          if (pages) {
            pages.forEach(p => templates.add(p.template_type))
          }

          if (templates.has('restaurant') || templates.has('catalog')) {
            dynamicNavItems.push({ href: '/dashboard/orders', label: 'Order Inbox', icon: ClipboardList as unknown, badge: 'LIVE' })
          }
          if (templates.has('booking')) {
            dynamicNavItems.push({ href: '/dashboard/bookings', label: 'Bookings (BMS)', icon: BookOpen as unknown })
          }
          if (templates.has('listing')) {
            dynamicNavItems.push({ href: '/dashboard/properties', label: 'Properties (PMS)', icon: FileText as unknown })
          }
          if (templates.has('rate_card') || templates.has('info') || templates.has('custom')) {
            dynamicNavItems.push({ href: '/dashboard/quotes', label: 'Quotes & Inquiries', icon: FileText as unknown })
          }
          
          dynamicNavItems.push({ href: '/dashboard/analytics', label: 'Deep Analytics', icon: TrendingUp as unknown })
          dynamicNavItems.push({ href: '/dashboard/forecast', label: 'Demand Forecast', icon: BarChart3 as unknown })
        }
      }
    }
  }

  const initialData: InitialDashboardData = {
    orgName,
    locations,
    activeLocationId,
    locationSlug,
    isOwnerOrManager,
    userEmail,
    credits,
    dynamicNavItems
  }

  return (
    <ClientLayout initialData={initialData}>
      {children}
    </ClientLayout>
  )
}


'use client'

import { useState, useEffect, useCallback } from 'react'
import { createClient } from '@/lib/supabase/client'
import { Bell } from 'lucide-react'
import { useAudioAlert } from '@/lib/hooks/use-audio'
import { formatCurrency } from '@/lib/utils/currency'
import Link from 'next/link'

type NotificationItem = {
  id: string
  type: 'order' | 'service_request' | 'booking' | 'inquiry'
  title: string
  subtitle: string
  href: string
  color: 'blue' | 'yellow' | 'violet' | 'emerald'
  timestamp: string
}

export function NotificationCenter() {
  const supabase = createClient()
  const [orgId, setOrgId] = useState<string | null>(null)
  const [items, setItems] = useState<NotificationItem[]>([])
  const [isOpen, setIsOpen] = useState(false)
  const { playChime } = useAudioAlert()

  // ── Initial org fetch ────────────────────────────────────────────────────────
  useEffect(() => {
    supabase.auth.getUser().then(({ data }) => {
      if (!data?.user?.id) return
      supabase
        .from('organization_members')
        .select('organizations(id)')
        .eq('user_id', data.user.id)
        .single()
        .then(({ data: m }) => {
          const id = m?.organizations?.id
          if (id) { setOrgId(id); return }
          // Fallback: owner who is not a member record
          supabase
            .from('organizations')
            .select('id')
            .eq('created_by', data.user.id)
            .single()
            .then(({ data: org }) => { if (org?.id) setOrgId(org.id) })
        })
    })
  }, []) 

  // ── Convert raw rows into NotificationItems ──────────────────────────────────
  const toOrderItem = (o: Record<string, unknown>): NotificationItem => ({
    id: o.id as string,
    type: 'order',
    title: 'New Order',
    subtitle: `Table ${o.table_identifier || 'Takeaway'} · ${formatCurrency((o.total_amount_minor as number) || 0, o.currency_code as string || 'NGN')}`,
    href: '/dashboard/orders',
    color: 'blue',
    timestamp: o.created_at as string,
  })

  const toRequestItem = (r: Record<string, unknown>): NotificationItem => ({
    id: r.id as string,
    type: 'service_request',
    title: `Table ${r.table_identifier}`,
    subtitle: `Needs ${r.request_type}`,
    href: '/dashboard/orders',
    color: 'yellow',
    timestamp: r.created_at as string,
  })

  const toBookingItem = (b: Record<string, unknown>): NotificationItem => ({
    id: b.id as string,
    type: 'booking',
    title: 'New Booking',
    subtitle: `${b.customer_name} · ${(b.location_pages as { title: string })?.title || 'Booking'}`,
    href: '/dashboard/manage/bookings',
    color: 'violet',
    timestamp: b.created_at as string,
  })

  const toInquiryItem = (i: Record<string, unknown>): NotificationItem => ({
    id: i.id as string,
    type: 'inquiry',
    title: 'New Enquiry',
    subtitle: `${i.customer_name} · ${(i.location_pages as { title: string })?.title || 'Page'}`,
    href: '/dashboard/manage/properties',
    color: 'emerald',
    timestamp: i.created_at as string,
  })

  // ── Initial data fetch ───────────────────────────────────────────────────────
  const fetchAll = useCallback(async (id: string) => {
    const [ordersRes, requestsRes, bookingsRes, inquiriesRes] = await Promise.all([
      supabase
        .from('orders')
        .select('id, table_identifier, total_amount_minor, created_at')
        .eq('organization_id', id)
        .in('status', ['pending', 'paid'])
        .order('created_at', { ascending: false })
        .limit(10),

      supabase
        .from('service_requests')
        .select('id, table_identifier, request_type, created_at')
        .eq('organization_id', id)
        .eq('status', 'pending')
        .order('created_at', { ascending: false })
        .limit(10),

      supabase
        .from('page_bookings')
        .select('id, customer_name, created_at, location_pages(title)')
        .eq('status', 'pending')
        .order('created_at', { ascending: false })
        .limit(10),

      supabase
        .from('page_inquiries')
        .select('id, customer_name, created_at, location_pages(title)')
        .eq('status', 'new')
        .order('created_at', { ascending: false })
        .limit(10),
    ])

    const all: NotificationItem[] = [
      ...(ordersRes.data || []).map(toOrderItem),
      ...(requestsRes.data || []).map(toRequestItem),
      ...(bookingsRes.data || []).map(toBookingItem),
      ...(inquiriesRes.data || []).map(toInquiryItem),
    ].sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime())

    setItems(all)
  }, [supabase])  

  useEffect(() => {
    if (!orgId) return

    fetchAll(orgId)
  }, [orgId, fetchAll])

  // ── Realtime subscriptions ───────────────────────────────────────────────────
  useEffect(() => {
    if (!orgId) return

    const channel = supabase
      .channel(`notification-${orgId}-${Math.random()}`)
      // Orders
      .on('postgres_changes', { event: '*', schema: 'public', table: 'orders', filter: `organization_id=eq.${orgId}` }, (payload: { eventType: string, new: Record<string, unknown> }) => {
        if (payload.eventType === 'INSERT') {
          if (['pending', 'paid'].includes(payload.new.status as string)) {
            playChime()
            setItems(prev => [toOrderItem(payload.new), ...prev])
          }
        } else if (payload.eventType === 'UPDATE') {
          if (['pending', 'paid'].includes(payload.new.status as string)) {
            setItems(prev => {
              const exists = prev.find(i => i.id === payload.new.id)
              return exists
                ? prev.map(i => i.id === payload.new.id ? toOrderItem(payload.new) : i)
                : [toOrderItem(payload.new), ...prev]
            })
          } else {
            setItems(prev => prev.filter(i => i.id !== payload.new.id))
          }
        }
      })
      // Service requests
      .on('postgres_changes', { event: '*', schema: 'public', table: 'service_requests', filter: `organization_id=eq.${orgId}` }, (payload: { eventType: string, new: Record<string, unknown> }) => {
        if (payload.eventType === 'INSERT' && payload.new.status === 'pending') {
          playChime()
          setItems(prev => [toRequestItem(payload.new), ...prev])
        } else if (payload.eventType === 'UPDATE') {
          if (payload.new.status === 'pending') {
            setItems(prev => {
              const exists = prev.find(i => i.id === payload.new.id)
              return exists ? prev.map(i => i.id === payload.new.id ? toRequestItem(payload.new) : i) : [toRequestItem(payload.new), ...prev]
            })
          } else {
            setItems(prev => prev.filter(i => i.id !== payload.new.id))
          }
        }
      })
      // Bookings — join via page_id → location → org
      .on('postgres_changes', { event: 'INSERT', schema: 'public', table: 'page_bookings' }, (payload: { new: { id: string } }) => {
        // We'll do a quick verify: fetch with org context
        supabase
          .from('page_bookings')
          .select('id, customer_name, created_at, location_pages(title, locations(organization_id))')
          .eq('id', payload.new.id)
          .single()
          .then(({ data }) => {
            if ((data as unknown as { location_pages?: { locations?: { organization_id?: string } } })?.location_pages?.locations?.organization_id === orgId) {
              playChime()
              setItems(prev => [toBookingItem(data as Record<string, unknown>), ...prev])
            }
          })
      })
      // Inquiries
      .on('postgres_changes', { event: 'INSERT', schema: 'public', table: 'page_inquiries' }, (payload: { new: { id: string } }) => {
        supabase
          .from('page_inquiries')
          .select('id, customer_name, created_at, location_pages(title, locations(organization_id))')
          .eq('id', payload.new.id)
          .single()
          .then(({ data }) => {
            if ((data as unknown as { location_pages?: { locations?: { organization_id?: string } } })?.location_pages?.locations?.organization_id === orgId) {
              playChime()
              setItems(prev => [toInquiryItem(data as Record<string, unknown>), ...prev])
            }
          })
      })
      .subscribe()

    return () => { supabase.removeChannel(channel) }
  }, [orgId]) 

  // ── App Badge API ────────────────────────────────────────────────────────────
  useEffect(() => {
    if ('setAppBadge' in navigator) {
      if (items.length > 0) {
        (navigator as unknown as { setAppBadge: (v: number) => Promise<void> }).setAppBadge(items.length).catch(console.error)
      } else {
        (navigator as unknown as { clearAppBadge: () => Promise<void> }).clearAppBadge().catch(console.error)
      }
    }
  }, [items.length])

  const colorMap = {
    blue: 'bg-blue-500/10 border-blue-500/20 hover:bg-blue-500/15',
    yellow: 'bg-yellow-500/10 border-yellow-500/20 hover:bg-yellow-500/15',
    violet: 'bg-violet-500/10 border-violet-500/20 hover:bg-violet-500/15',
    emerald: 'bg-emerald-500/10 border-emerald-500/20 hover:bg-emerald-500/15',
  }

  const labelColorMap = {
    blue: 'text-blue-400',
    yellow: 'text-yellow-400',
    violet: 'text-violet-400',
    emerald: 'text-emerald-400',
  }

  return (
    <div className="relative">
      <button
        onClick={() => setIsOpen(!isOpen)}
        className="relative p-2 rounded-full hover:bg-white/5 transition-colors text-zinc-400 hover:text-white"
      >
        <Bell className="w-5 h-5" />
        {items.length > 0 && (
          <span className="absolute top-1.5 right-1.5 w-2 h-2 rounded-full bg-red-500 animate-pulse border border-zinc-950" />
        )}
      </button>

      {isOpen && (
        <>
          <div className="fixed inset-0 z-40" onClick={() => setIsOpen(false)} />
          <div className="absolute right-0 mt-2 w-80 bg-zinc-900 border border-zinc-800 rounded-xl shadow-2xl z-50 overflow-hidden">
            <div className="p-3 border-b border-zinc-800 bg-zinc-950/50 flex justify-between items-center">
              <span className="font-bold text-sm text-white">Notifications</span>
              <span className="text-xs font-medium text-zinc-500">{items.length} unread</span>
            </div>

            <div className="max-h-[60vh] overflow-y-auto">
              {items.length === 0 ? (
                <div className="p-8 text-center text-zinc-500 text-sm">
                  You&apos;re all caught up!
                </div>
              ) : (
                <div className="p-2 space-y-1">
                  {items.map(item => (
                    <Link
                      key={`${item.type}-${item.id}`}
                      href={item.href}
                      onClick={() => setIsOpen(false)}
                      className={`block p-3 rounded-lg border transition-colors ${colorMap[item.color]}`}
                    >
                      <div className={`text-xs font-bold mb-0.5 uppercase tracking-wider ${labelColorMap[item.color]}`}>
                        {item.title}
                      </div>
                      <div className="text-sm text-white font-medium">{item.subtitle}</div>
                    </Link>
                  ))}
                </div>
              )}
            </div>

            <Link
              href="/dashboard"
              onClick={() => setIsOpen(false)}
              className="block p-3 text-center text-xs font-bold text-zinc-400 bg-zinc-950 hover:bg-zinc-900 transition-colors border-t border-zinc-800"
            >
              View Dashboard →
            </Link>
          </div>
        </>
      )}
    </div>
  )
}

'use server'

import { createClient } from '@/lib/supabase/server'
import { redirect } from 'next/navigation'

export async function searchDirectory(formData: FormData) {
  const query = formData.get('query')?.toString().trim()

  if (!query) {
    return { error: 'Please enter a venue name' }
  }

  const supabase = await createClient()

  // Find location by name match

  const { data: locMatch, error } = await supabase
    .from('location_pages')
    .select('slug, locations!inner(name)')
    .or(`slug.ilike.%${query}%,locations.name.ilike.%${query}%`)
    .eq('is_published', true)
    .limit(1)
    .maybeSingle()

  if (locMatch) {
    redirect(`/m/${locMatch.slug}`)
  }

  return { error: `No active venue found matching "${query}".` }
}

