'use client'



import { useState } from 'react'
import { useRouter } from 'next/navigation'
import { toast } from 'sonner'
import { addPageItem, updatePageItem, deletePageItem } from '../(dashboard)/dashboard/pages/actions'
import { AiGenerateButton } from './ai-generate-button'
import { formatCurrency } from '@/lib/utils/currency'

interface PageItem {
  id: string
  title: string
  subtitle: string | null
  description: string | null
  price_minor: number | null
  price_display: string | null
  availability_status: string
  item_data: Record<string, string>
  deposit_percentage: number | null
  payment_mode: string
  inventory_count: number | null
}

interface PageBuilderFormProps {
  pageId: string
  templateType: string
  initialItems: PageItem[]
  orgId: string
}

export function PageBuilderForm({ pageId, templateType, initialItems, orgId }: PageBuilderFormProps) {


  const [items, setItems] = useState<PageItem[]>(initialItems)
  const [isAdding, setIsAdding] = useState(false)
  const [editingId, setEditingId] = useState<string | null>(null)
  const [isSaving, setIsSaving] = useState(false)
  const router = useRouter()

  const handleAddSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault()
    setIsSaving(true)
    const formData = new FormData(e.currentTarget)
    formData.append('page_id', pageId)

    // Depending on templateType, format item_data properly if needed.
    if (templateType === 'catalog') {
      const category = formData.get('category') as string
      if (category) {
        formData.set('item_data', JSON.stringify({ category }))
      }
    } else if (templateType === 'quote') {
      const unit = formData.get('unit') as string
      const price_range = formData.get('price_range') as string
      const turnaround = formData.get('turnaround') as string
      formData.set('item_data', JSON.stringify({ unit, price_range, turnaround }))
    }

    try {
      await addPageItem(formData)
      setIsAdding(false)
      toast.success('Item added successfully')
      // Force refresh to get new items
      router.refresh()
    } catch (err) {
      console.error(err)
      toast.error('Failed to add item')
    } finally {
      setIsSaving(false)
    }
  }

  const handleEditSubmit = async (e: React.FormEvent<HTMLFormElement>, itemId: string) => {
    e.preventDefault()
    setIsSaving(true)
    const formData = new FormData(e.currentTarget)
    formData.append('itemId', itemId)

    if (templateType === 'catalog') {
      const category = formData.get('category') as string
      if (category) {
        formData.set('item_data', JSON.stringify({ category }))
      }
    } else if (templateType === 'quote') {
      const unit = formData.get('unit') as string
      const price_range = formData.get('price_range') as string
      const turnaround = formData.get('turnaround') as string
      formData.set('item_data', JSON.stringify({ unit, price_range, turnaround }))
    }

    try {
      await updatePageItem(formData)
      setEditingId(null)
      toast.success('Item updated successfully')
      router.refresh()
    } catch (err) {
      console.error(err)
      toast.error('Failed to update item')
    } finally {
      setIsSaving(false)
    }
  }

  const handleDelete = async (itemId: string) => {
    if (!confirm('Are you sure you want to delete this item?')) return
    setIsSaving(true)
    const formData = new FormData()
    formData.append('itemId', itemId)
    try {
      await deletePageItem(formData)
      toast.success('Item deleted')
      router.refresh()
    } catch (err) {
      console.error(err)
      toast.error('Failed to delete item')
    } finally {
      setIsSaving(false)
    }
  }

  const handleAIGenerate = async (formId: string) => {
    const form = document.getElementById(formId) as HTMLFormElement
    if (!form) return

    const titleInput = form.elements.namedItem('title') as HTMLInputElement
    const title = titleInput?.value
    if (!title) {
      toast.error('Please enter a title first to generate a description.')
      return
    }

    try {
      const res = await fetch('/api/ai/generate-content', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          title,
          templateType,
        })
      })

      if (!res.ok) throw new Error('Failed to generate')
      const { text } = await res.json()

      const textarea = form.elements.namedItem('description') as HTMLTextAreaElement
      if (textarea) {
        textarea.value = text
      }
    } catch (err) {
      console.error('AI Gen Error:', err)
      toast.error('Failed to generate description. Please try again.')
