interface ShareModalProps {
  isOpen: boolean
  onClose: () => void
  url: string
  title: string
  description?: string
}

export function ShareModal({ isOpen, onClose, url, title, description }: ShareModalProps) {
  const [copied, setCopied] = useState(false)

  const copyToClipboard = async () => {
    try {
      await navigator.clipboard.writeText(url)
      setCopied(true)
      setTimeout(() => setCopied(false), 2000)
    } catch (err) {
      console.error('Failed to copy', err)
    }
  }

  const encodedUrl = encodeURIComponent(url)
  const encodedTitle = encodeURIComponent(title)
  const encodedDesc = encodeURIComponent(description || title)

  const shareLinks = [
    {
      id: 'whatsapp',
      name: 'WhatsApp',
      icon: WhatsAppIcon,
      color: 'bg-[#25D366] text-white',
      href: `https://wa.me/?text=${encodedTitle}%20${encodedUrl}`,
    },
    {
      id: 'twitter',
      name: 'X (Twitter)',
      icon: TwitterIcon,
      color: 'bg-black text-white border border-zinc-800',
      href: `https://twitter.com/intent/tweet?url=${encodedUrl}&text=${encodedTitle}`,
    },
    {
      id: 'facebook',
      name: 'Facebook',
      icon: FacebookIcon,
      color: 'bg-[#1877F2] text-white',
      href: `https://www.facebook.com/sharer/sharer.php?u=${encodedUrl}`,
    },
    {
      id: 'snapchat',
      name: 'Snapchat',
      icon: SnapchatIcon,
      color: 'bg-[#FFFC00] text-black',
      href: `https://snapchat.com/scan?attachmentUrl=${encodedUrl}`,
    },
    {
      id: 'linkedin',
      name: 'LinkedIn',
      icon: LinkedinIcon,
      color: 'bg-[#0A66C2] text-white',
      href: `https://www.linkedin.com/shareArticle?mini=true&url=${encodedUrl}&title=${encodedTitle}&summary=${encodedDesc}`,
    },
    {
      id: 'sms',
      name: 'Message',
      icon: MessageCircle,
      color: 'bg-emerald-500 text-white',
      href: `sms:?&body=${encodedTitle}%20${encodedUrl}`,
    },
  ]

  return (
    <AnimatePresence>
      {isOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            onClick={onClose}
            className="absolute inset-0 bg-black/60 backdrop-blur-sm"
          />

          <motion.div
            initial={{ scale: 0.95, opacity: 0, y: 20 }}
            animate={{ scale: 1, opacity: 1, y: 0 }}
            exit={{ scale: 0.95, opacity: 0, y: 20 }}
            className="relative w-full max-w-sm bg-zinc-950 border border-zinc-800 rounded-3xl shadow-2xl overflow-hidden p-6"
          >
            <button
              onClick={onClose}
              className="absolute top-4 right-4 w-8 h-8 flex items-center justify-center rounded-full bg-zinc-900 text-zinc-400 hover:text-white hover:bg-zinc-800 transition-colors"
            >
              <X className="w-5 h-5" />
            </button>

            <div className="mb-6">
              <h3 className="text-xl font-bold text-white mb-1">Share this page</h3>
  { }

              <p className="text-sm text-zinc-400">Share "{title}" with your friends or community.</p>
            </div>

            <div className="grid grid-cols-3 gap-4 mb-8">
              {shareLinks.map((link) => {
                const Icon = link.icon
                return (
                  <a
                    key={link.id}
                    href={link.href}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="flex flex-col items-center gap-2 group"
                  >
                    <div className={`w-14 h-14 rounded-2xl flex items-center justify-center shadow-lg transition-transform group-hover:scale-110 ${link.color}`}>
                      <Icon className="w-6 h-6" />
                    </div>
                    <span className="text-[11px] font-medium text-zinc-400 group-hover:text-zinc-300">{link.name}</span>
                  </a>
                )
              })}
            </div>

            <div className="relative">
              <div className="flex items-center gap-2 p-2 bg-zinc-900 border border-zinc-800 rounded-xl">
                <input
                  type="text"
                  readOnly
                  value={url}
                  className="flex-1 bg-transparent border-none text-sm text-zinc-300 px-2 outline-none w-full"
                />
                <button
                  onClick={copyToClipboard}
                  className={`flex items-center gap-1.5 px-3 py-2 rounded-lg text-sm font-medium transition-all ${
                    copied ? 'bg-emerald-500/20 text-emerald-400' : 'bg-zinc-800 text-white hover:bg-zinc-700'
                  }`}
                >
                  {copied ? <CheckCircle2 className="w-4 h-4" /> : <Copy className="w-4 h-4" />}
                  {copied ? 'Copied' : 'Copy'}
                </button>
              </div>
            </div>
          </motion.div>
        </div>
      )}
    </AnimatePresence>
  )
}

'use server'

import { revalidatePath } from 'next/cache'
import { redirect } from 'next/navigation'
import { createClient, createAdminClient } from '@/lib/supabase/server'
import { sendWelcomeEmail } from '@/lib/notifications/email'
import { z } from 'zod'
import { actionClient } from '@/lib/safe-action'

const loginSchema = z.object({
  email: z.string().email('Please enter a valid email address'),
  password: z.string().min(1, 'Password is required'),
  redirectTo: z.string().optional()
})

const signupSchema = z.object({
  email: z.string().email('Please enter a valid email address'),
  password: z.string().min(8, 'Password must be at least 8 characters'),
  redirectTo: z.string().optional()
})

/** Sanitize redirect target to prevent open redirect attacks */
function sanitizeRedirect(target: string | null): string {
  if (!target || !target.startsWith('/') || target.startsWith('//')) {
    return '/dashboard'
  }
  return target
}

export const login = actionClient
  .schema(loginSchema)
  .action(async ({ parsedInput: { email, password, redirectTo: rawRedirect } }) => {
    const supabase = await createClient()
    const redirectTo = sanitizeRedirect(rawRedirect || null)

    // If a demo user is currently logged in, clear their session before proceeding
    const { data: { user } } = await supabase.auth.getUser()
    if (user && user.email?.includes('demo-') && user.email?.includes('@ourmenuos.online')) {
      await supabase.auth.signOut()
    }

    const { error } = await supabase.auth.signInWithPassword({ email, password })

    if (error) {
      redirect(`/login?message=${encodeURIComponent('Could not authenticate user')}&redirectTo=${encodeURIComponent(redirectTo)}`)
    }

    revalidatePath('/', 'layout')
    redirect(redirectTo)
  })

export const signup = actionClient
  .schema(signupSchema)
  .action(async ({ parsedInput: { email, password, redirectTo: rawRedirect } }) => {
    const supabase = await createClient()
    const redirectTo = sanitizeRedirect(rawRedirect || null)

    // If a demo user is currently logged in, clear their session before proceeding
    const { data: { user } } = await supabase.auth.getUser()
    if (user && user.email?.includes('demo-') && user.email?.includes('@ourmenuos.online')) {
      await supabase.auth.signOut()
    }

    const { error, data } = await supabase.auth.signUp({ email, password })

    if (error) {
      redirect(`/login?message=${encodeURIComponent('Could not sign up user')}&redirectTo=${encodeURIComponent(redirectTo)}`)
    }

    // Trigger welcome email in the background
    sendWelcomeEmail(email).catch(console.error)

    revalidatePath('/', 'layout')
    redirect(redirectTo)
  })

export async function signInWithGoogle() {
  const supabase = await createClient()
  const { headers } = await import('next/headers')
  
  const headersList = await headers()
  const host = headersList.get('host') || 'localhost:3000'
  const protocol = host.includes('localhost') ? 'http' : 'https'
  const origin = `${protocol}://${host}`
  
  const { data, error } = await supabase.auth.signInWithOAuth({
    provider: 'google',
    options: {
      redirectTo: `${origin}/auth/callback`,
    },
  })

  if (error) {
    redirect(`/login?message=Could not authenticate via Google`)
  }

  if (data.url) {
    redirect(data.url)
  }
}

