'use client'

import { use } from 'react'
import { useState } from 'react'
import { motion } from 'framer-motion'
import { verifyFeedbackPin } from './actions'
import { toast } from 'sonner'
import { useRouter } from 'next/navigation'

export default function FeedbackVerifyPage({
  params
}: {
  params: Promise<{ slug: string }>
}) {
  const { slug } = use(params)
  const [pin, setPin] = useState('')
  const [isLoading, setIsLoading] = useState(false)
  const router = useRouter()

  const handleVerify = async (e: React.FormEvent) => {
    e.preventDefault()
    if (pin.length !== 4) {
      toast.error('PIN must be 4 digits')
      return
    }

    setIsLoading(true)
    try {
      const { orderId, error } = await verifyFeedbackPin(slug, pin)
      if (error) {
        toast.error(error)
        setPin('')
      } else if (orderId) {
        toast.success('Verified!')
        router.push(`/m/${slug}/feedback/${orderId}`)
      }

    } catch (err) {
      toast.error('Failed to verify PIN')
    } finally {
      setIsLoading(false)
    }
  }

  return (
    <div className="min-h-screen bg-black flex flex-col items-center justify-center p-6">
      <motion.div 
        initial={{ opacity: 0, scale: 0.95, y: 20 }}
        animate={{ opacity: 1, scale: 1, y: 0 }}
        className="max-w-sm w-full bg-zinc-900 border border-zinc-800 rounded-3xl p-8 shadow-2xl relative overflow-hidden"
      >
        <div className="absolute top-0 left-1/2 -translate-x-1/2 w-full h-32 bg-blue-500/10 blur-3xl rounded-full" />

        <div className="relative z-10 text-center space-y-6">
          <div className="w-16 h-16 bg-blue-500/20 text-blue-400 rounded-full flex items-center justify-center mx-auto shadow-[0_0_30px_rgba(59,130,246,0.2)]">
            <svg className="w-8 h-8" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8V7a4 4 0 00-8 0v4h8z" /></svg>
          </div>

          <div>
            <h1 className="text-2xl font-black text-white">Enter Receipt PIN</h1>
            <p className="text-zinc-400 text-sm mt-2">
              To rate and tip the staff, please enter the 4-digit PIN found on your receipt or order confirmation.
            </p>
          </div>

          <form onSubmit={handleVerify} className="space-y-4 pt-2">
            <input 
              type="text"
              maxLength={4}
              value={pin}
              onChange={(e) => setPin(e.target.value.replace(/[^0-9]/g, ''))}
              placeholder="0000"
              className="w-full h-16 text-center text-3xl tracking-[1em] pl-[1em] font-mono bg-zinc-950 border border-zinc-800 rounded-xl text-white outline-none focus:border-blue-500 transition-colors"
            />
            <button 
              type="submit"
              disabled={pin.length !== 4 || isLoading}
              className="w-full bg-blue-600 text-white font-bold py-4 rounded-xl shadow-[0_0_20px_rgba(37,99,235,0.3)] hover:bg-blue-500 transition-colors disabled:opacity-50"
            >
              {isLoading ? 'Verifying...' : 'Verify & Continue'}
            </button>
            <div className="pt-4 border-t border-zinc-800">
              <button
                type="button"
                onClick={() => router.push(`/m/${slug}/feedback/general`)}
                className="w-full text-zinc-500 text-sm font-medium hover:text-white transition-colors"
              >
                I don&apos;t have an order (General Feedback)
              </button>
            </div>
          </form>
        </div>
      </motion.div>
    </div>
  )
}

'use client'

import { use } from 'react'
import { useState, useEffect } from 'react'
import { motion } from 'framer-motion'
import { toast } from 'sonner'
import { submitFeedbackAndTip } from './actions'

export default function FeedbackPage({
  params
}: {
  params: Promise<{ slug: string, order_id: string }>
}) {
  const { slug, order_id } = use(params)
  const isGeneral = order_id === 'general'

  const [staffRating, setStaffRating] = useState(0)
  const [staffFeedback, setStaffFeedback] = useState('')

  const [businessRating, setBusinessRating] = useState(0)
  const [businessFeedback, setBusinessFeedback] = useState('')

  const [tipSelection, setTipSelection] = useState<'0' | '10' | '15' | '20' | 'custom'>('0')
  const [customTip, setCustomTip] = useState('')

  const [isSubmitting, setIsSubmitting] = useState(false)
  const [submitted, setSubmitted] = useState(false)

  // Quick info logic
  const [locationId, setLocationId] = useState<string | null>(null)

  useEffect(() => {
    if (isGeneral) {
      const urlParams = new URLSearchParams(window.location.search)
      Promise.resolve().then(() => setLocationId(urlParams.get('location_id')))
    }
  }, [isGeneral])

  const handleFeedbackSubmit = async () => {
    if (!isGeneral && staffRating === 0 && businessRating === 0 && tipSelection === '0') {
      toast.error('Please leave a rating or a tip to submit.')
      return
    }
    if (isGeneral && businessRating === 0) {
      toast.error('Please select a star rating for the business.')
      return
    }

    setIsSubmitting(true)
    try {
      const { checkoutUrl, error } = await submitFeedbackAndTip(
        slug,
        isGeneral ? null : order_id,
        locationId,
        staffRating,
        staffFeedback,
        businessRating,
        businessFeedback,
        tipSelection,
        customTip
      )

      if (error) {
        toast.error(error)
        return
      }

      if (checkoutUrl) {
        window.location.href = checkoutUrl
      } else {
        setSubmitted(true)
        toast.success('Thank you for your feedback!')
      }

    } catch (e) {
      toast.error('Something went wrong submitting your review.')
    } finally {
      setIsSubmitting(false)
    }
  }

  if (submitted) {
    return (
      <div className="min-h-screen bg-black flex flex-col items-center justify-center p-6">
        <div className="w-16 h-16 bg-green-500/20 text-green-500 rounded-full flex items-center justify-center mb-6">
          <svg className="w-8 h-8" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" /></svg>
        </div>
        <h1 className="text-3xl font-black text-white mb-2">Thank You!</h1>
        <p className="text-zinc-400 text-center max-w-sm mb-8">
          Your feedback has been submitted successfully. We appreciate your business and hope to see you again soon.
        </p>
        <button 
          onClick={() => window.location.href = `/m/${slug}`}
          className="px-6 py-3 rounded-xl bg-zinc-800 text-white font-medium hover:bg-zinc-700 transition-colors"
        >
          Return to Menu
        </button>
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-black flex flex-col items-center justify-center p-4">
      <motion.div
        initial={{ y: 20, opacity: 0 }}
        animate={{ y: 0, opacity: 1 }}
        className="w-full max-w-md bg-zinc-900 border border-zinc-800 rounded-3xl p-6 shadow-2xl relative"
      >
        <div className="text-center mb-8">
          <h2 className="text-2xl font-black text-white">How was your experience?</h2>
          <p className="text-zinc-400 mt-2">Your honest feedback helps us improve.</p>
        </div>

        <div className="space-y-10">

          {/* BUSINESS RATING */}
          <div className="space-y-4">
            <h3 className="text-sm font-bold uppercase tracking-widest text-zinc-500 text-center">Rate the Food & Restaurant</h3>
            <div className="flex justify-center gap-2">
              {[1, 2, 3, 4, 5].map((star) => (
                <button
                  key={`biz-${star}`}
                  onClick={() => setBusinessRating(star)}
                  className={`text-4xl transition-transform hover:scale-110 ${businessRating >= star ? 'text-blue-500 drop-shadow-[0_0_10px_rgba(59,130,246,0.5)]' : 'text-zinc-800'}`}
                >
                  ★
                </button>
              ))}
            </div>
            {businessRating > 0 && (
              <motion.textarea
                initial={{ opacity: 0, height: 0 }}
                animate={{ opacity: 1, height: 'auto' }}
                value={businessFeedback}
                onChange={(e) => setBusinessFeedback(e.target.value)}
                placeholder="What did you love? What could be better?"
                className="w-full h-24 bg-zinc-950 border border-zinc-800 rounded-xl px-4 py-3 text-white outline-none focus:border-blue-500 resize-none text-sm"
              />
            )}
          </div>

          {/* STAFF RATING & TIPPING (Only if tied to an order) */}
          {!isGeneral && (
            <div className="space-y-4 pt-6 border-t border-zinc-800/50">
              <h3 className="text-sm font-bold uppercase tracking-widest text-zinc-500 text-center">Rate your Waiter</h3>
              <div className="flex justify-center gap-2">
                {[1, 2, 3, 4, 5].map((star) => (
                  <button
                    key={`staff-${star}`}
                    onClick={() => setStaffRating(star)}
                    className={`text-4xl transition-transform hover:scale-110 ${staffRating >= star ? 'text-yellow-400 drop-shadow-[0_0_10px_rgba(250,204,21,0.5)]' : 'text-zinc-800'}`}
                  >
                    ★
                  </button>
                ))}
              </div>
              {staffRating > 0 && (
                <motion.textarea
                  initial={{ opacity: 0, height: 0 }}
                  animate={{ opacity: 1, height: 'auto' }}
                  value={staffFeedback}
                  onChange={(e) => setStaffFeedback(e.target.value)}
                  placeholder="Any specific feedback for your waiter? (Optional)"
                  className="w-full h-24 bg-zinc-950 border border-zinc-800 rounded-xl px-4 py-3 text-white outline-none focus:border-yellow-500 resize-none text-sm"
                />
              )}

              <div className="pt-6">
                <label className="block text-sm font-medium text-zinc-300 mb-3 text-center">Leave a Tip for Flawless Service?</label>
                <div className="grid grid-cols-5 gap-2 mb-2">
                  {[
                    { val: '0', label: 'None' },
                    { val: '10', label: '10%' },
                    { val: '15', label: '15%' },
                    { val: '20', label: '20%' },
                    { val: 'custom', label: 'Custom' }
                  ].map(btn => (
                    <button
                      key={btn.val}

                  onClick={() => setTipSelection(btn.val as '0' | '10' | '15' | '20' | 'custom')}
                      className={`py-2 text-sm rounded-lg font-medium transition-colors border ${tipSelection === btn.val ? 'bg-zinc-100 border-zinc-100 text-black' : 'bg-transparent border-zinc-800 text-zinc-400 hover:bg-zinc-800 hover:text-white'}`}
                    >
                      {btn.label}
                    </button>
                  ))}
                </div>
                {tipSelection === 'custom' && (
                  <motion.input 
                    initial={{ opacity: 0, y: -10 }}
                    animate={{ opacity: 1, y: 0 }}
                    type="number" 
                    min="0"
                    step="100"
                    value={customTip}
                    onChange={(e) => setCustomTip(e.target.value)}
                    placeholder="Enter custom amount"
                    className="w-full bg-zinc-950 border border-zinc-800 rounded-xl px-4 py-3 text-white outline-none focus:border-zinc-500 mt-2"
                  />
                )}
              </div>
            </div>
          )}

          <div className="pt-6">
            <button 
              onClick={handleFeedbackSubmit}
              disabled={isSubmitting}
              className="w-full bg-blue-600 text-white font-bold py-4 rounded-xl shadow-[0_0_20px_rgba(37,99,235,0.3)] flex items-center justify-center disabled:opacity-50 hover:bg-blue-500 transition-colors"
            >
              {isSubmitting ? 'Submitting...' : (tipSelection !== '0' ? 'Submit & Pay Tip' : 'Submit Feedback')}
            </button>
            <button 
              onClick={() => window.location.href = `/m/${slug}`}
              className="w-full py-4 text-zinc-500 text-sm font-medium hover:text-zinc-300 transition-colors mt-2"
            >
              Skip & Return to Menu
            </button>
          </div>
        </div>
      </motion.div>
    </div>
  )
}

'use client'

import { useEffect, useState } from 'react'
import { createClient } from '@/lib/supabase/client'
import { motion, AnimatePresence } from 'framer-motion'
import { Tables } from '@/types'

interface LiveOrderTrackerProps {
  organizationId: string
  locationId: string
}



export function LiveOrderTracker({ organizationId, locationId }: LiveOrderTrackerProps) {
  const supabase = createClient()
  const [order, setOrder] = useState<Tables<'orders'> | null>(null)
  const [timeLeft, setTimeLeft] = useState<number>(0)



  const [isSubmitting, setIsSubmitting] = useState(false)

  useEffect(() => {
    const activeOrderId = localStorage.getItem('activeOrderId')
    if (!activeOrderId) return

    // Fetch initial order state
    const fetchOrder = async () => {
      const { data } = await supabase.from('orders').select('*').eq('id', activeOrderId).single()
      if (data) {
        setOrder(data)
      }
    }
    fetchOrder()

    // Subscribe to realtime updates
    const channel = supabase
      .channel(`order-${activeOrderId}`)
      .on('postgres_changes', {
        event: 'UPDATE',
        schema: 'public',
        table: 'orders',
        filter: `id=eq.${activeOrderId}`
      }, (payload) => {
        setOrder(payload.new as Tables<'orders'>)
      })
      .subscribe()

    return () => {
      supabase.removeChannel(channel)
    }
  }, [supabase])

  // Countdown timer logic
  useEffect(() => {
    if (!order || order.status !== 'preparing' || !order.estimated_ready_at) return

    const interval = setInterval(() => {
      const target = order.estimated_ready_at ? new Date(order.estimated_ready_at).getTime() : 0
      const now = new Date().getTime()
      const diff = Math.max(0, Math.floor((target - now) / 1000))
      setTimeLeft(diff)
    }, 1000)

    return () => clearInterval(interval)
  }, [order])

  // Feedback logic moved to standalone page

  if (!order) return null

  const formatTime = (seconds: number) => {
    const m = Math.floor(seconds / 60)
    const s = seconds % 60
    return `${m}m ${s}s`
  }

  return (
    <>
      <AnimatePresence>
        {order.status === 'preparing' && (
          <motion.div
            layout
            initial={{ opacity: 0, y: -50, scale: 0.95 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, y: -50, scale: 0.95 }}
            transition={{ type: 'spring', damping: 25 }}
            className="sticky top-4 z-40 w-full bg-zinc-900/90 backdrop-blur-xl border border-blue-500/30 rounded-2xl py-3 px-5 shadow-[0_10px_40px_rgba(0,0,0,0.5)] overflow-hidden flex items-center justify-between mb-6"
          >
            {/* Progress Bar Background */}
            <div 
              className="absolute inset-0 bg-blue-500/20" 
              style={{ width: `${Math.min(100, Math.max(0, 100 - (timeLeft / ((order.estimated_prep_time_minutes || 1) * 60)) * 100))}%`, transition: 'width 1s linear' }} 
            />

            <div className="relative z-10 flex items-center gap-3">
              <div className="w-8 h-8 rounded-full bg-blue-500/20 flex items-center justify-center">
                <span className="w-2.5 h-2.5 rounded-full bg-blue-500 animate-pulse" />
              </div>
              <div className="flex flex-col">
                <span className="text-white font-bold text-sm leading-tight">Preparing Order #{order.id.split('-')[0]}</span>
                <span className="text-zinc-400 text-xs font-medium">Your meal is on the way</span>
              </div>
            </div>

            <div className="relative z-10 text-right pl-4 border-l border-white/10">
              <span className="text-[10px] text-zinc-400 font-bold uppercase tracking-widest block leading-none mb-1">Ready In</span>
              <span className="text-blue-400 font-black font-mono tracking-tighter text-lg leading-none">
                {formatTime(timeLeft)}
              </span>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      {order.status === 'completed' && (
        <motion.div
          initial={{ opacity: 0, scale: 0.95 }}
          animate={{ opacity: 1, scale: 1 }}
          className="mt-8 bg-green-500/10 border border-green-500/20 rounded-2xl p-6 text-center"
        >
          <div className="w-16 h-16 bg-green-500/20 text-green-500 rounded-full flex items-center justify-center mx-auto mb-4">
            <svg className="w-8 h-8" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" /></svg>
          </div>
          <h2 className="text-2xl font-black text-white mb-2">Enjoy your meal!</h2>
          <p className="text-zinc-400 mb-6">Your order has been completed and delivered.</p>
          <button
            onClick={() => window.location.href = `/m/${window.location.pathname.split('/')[2]}/feedback/${order.id}`}
            className="w-full py-4 rounded-xl bg-blue-600 hover:bg-blue-500 text-white font-bold text-lg transition-colors"
          >
            Leave Feedback & Tip
          </button>
        </motion.div>
      )}
    </>
  )
}

